import React, { useState } from 'react';
import { ShieldCheck, Key, Lock, Check, X } from 'lucide-react';
import { apiClient } from '../api';
import { Button } from '../design-system';

interface AccessKeyModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSaved?: () => void;
}

export const AccessKeyModal: React.FC<AccessKeyModalProps> = ({
  isOpen,
  onClose,
  onSaved,
}) => {
  const [keyInput, setKeyInput] = useState(apiClient.getAccessKey() || '');
  const [isSaved, setIsSaved] = useState(false);

  if (!isOpen) return null;

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = keyInput.trim();
    apiClient.setAccessKey(trimmed || null);
    setIsSaved(true);
    if (onSaved) {
      onSaved();
    }
    setTimeout(() => {
      setIsSaved(false);
      onClose();
    }, 600);
  };

  const handleClear = () => {
    apiClient.setAccessKey(null);
    setKeyInput('');
    if (onSaved) {
      onSaved();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xs animate-in fade-in">
      <div className="bg-slate-900 border border-slate-800 rounded-xl p-6 max-w-md w-full shadow-2xl space-y-4">
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-lg bg-indigo-500/10 text-indigo-400 border border-indigo-500/20">
              <ShieldCheck className="h-6 w-6" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-100">Tower 单租户访问密钥</h3>
              <p className="text-xs text-slate-400">
                经请求头 <code>X-CT-Access-Key</code> 传递 (CH-08 / N05)
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-md text-slate-400 hover:text-slate-200 hover:bg-slate-800 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <form onSubmit={handleSave} className="space-y-4 pt-1">
          <div>
            <label className="block text-xs font-medium text-slate-300 mb-1">
              API 访问密钥 (高熵密钥)
            </label>
            <div className="relative">
              <input
                type="password"
                value={keyInput}
                onChange={(e) => setKeyInput(e.target.value)}
                placeholder="输入后端配置的 CT_ACCESS_KEY..."
                className="w-full bg-slate-950 border border-slate-700 rounded-lg text-slate-100 text-sm pl-9 pr-3 py-2 font-mono focus:outline-hidden focus:border-indigo-500"
                autoFocus
              />
              <Key className="absolute left-3 top-2.5 h-4 w-4 text-slate-500 pointer-events-none" />
            </div>
          </div>

          <div className="text-[11px] text-slate-400 leading-relaxed bg-slate-950/60 p-3 rounded-lg border border-slate-800 space-y-1">
            <div className="flex items-center gap-1.5 text-indigo-300 font-medium">
              <Lock className="h-3 w-3" />
              <span>内存安全凭据</span>
            </div>
            <p>
              密钥仅保留在当前前端实例内存中，不写入 localStorage、URL 或持久日志。连接真实后端 API 绝不伪造或透传内部凭证。
            </p>
          </div>

          <div className="flex items-center justify-between pt-2">
            {apiClient.getAccessKey() ? (
              <button
                type="button"
                onClick={handleClear}
                className="text-xs text-rose-400 hover:text-rose-300 underline cursor-pointer"
              >
                清除当前密钥
              </button>
            ) : (
              <div />
            )}
            <div className="flex gap-2">
              <Button type="button" variant="ghost" size="sm" onClick={onClose}>
                取消
              </Button>
              <Button type="submit" variant="primary" size="sm">
                {isSaved ? (
                  <>
                    <Check className="h-3.5 w-3.5 mr-1 text-emerald-400" />
                    已保存！
                  </>
                ) : (
                  '保存密钥'
                )}
              </Button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};
