import React from 'react';
import { AlertTriangle, AlertCircle, Info, RefreshCw } from 'lucide-react';
import type { ErrorCode } from '../types';

interface AlertBannerProps {
  type?: 'warning' | 'error' | 'info' | 'partial';
  title?: string;
  message: React.ReactNode;
  errorCode?: ErrorCode | string;
  requestId?: string;
  onRetry?: () => void;
  className?: string;
}

export const AlertBanner: React.FC<AlertBannerProps> = ({
  type = 'warning',
  title,
  message,
  errorCode,
  requestId,
  onRetry,
  className = '',
}) => {
  const styles = {
    warning: 'border-amber-700/80 bg-amber-950/40 text-amber-200',
    error: 'border-rose-800 bg-rose-950/50 text-rose-200',
    info: 'border-blue-800 bg-blue-950/40 text-blue-200',
    partial: 'border-yellow-700/80 bg-yellow-950/40 text-yellow-200',
  };

  const icons = {
    warning: <AlertTriangle className="h-5 w-5 text-amber-400 shrink-0 mt-0.5" />,
    error: <AlertCircle className="h-5 w-5 text-rose-400 shrink-0 mt-0.5" />,
    info: <Info className="h-5 w-5 text-blue-400 shrink-0 mt-0.5" />,
    partial: <AlertTriangle className="h-5 w-5 text-yellow-400 shrink-0 mt-0.5" />,
  };

  return (
    <div className={`flex items-start gap-3 p-4 rounded-xl border ${styles[type]} ${className}`}>
      {icons[type]}
      <div className="flex-1 text-xs space-y-1">
        <div className="flex items-center gap-2 flex-wrap">
          {title && <span className="font-semibold text-sm">{title}</span>}
          {errorCode && (
            <span className="font-mono px-2 py-0.5 rounded bg-black/40 border border-white/10 text-[10px] font-bold tracking-wide">
              {errorCode}
            </span>
          )}
          {requestId && (
            <span className="font-mono text-slate-400 text-[10px]">
              Req ID: {requestId}
            </span>
          )}
        </div>
        <div className="text-slate-300 leading-relaxed">{message}</div>
      </div>
      {onRetry && (
        <button
          onClick={onRetry}
          className="shrink-0 p-1.5 rounded-lg bg-white/10 hover:bg-white/20 text-white transition-colors flex items-center gap-1 text-xs font-medium cursor-pointer"
        >
          <RefreshCw className="h-3.5 w-3.5" />
          重试
        </button>
      )}
    </div>
  );
};
