import React from 'react';
import { Server, Cpu } from 'lucide-react';
import type { NodeList, Node } from '../types';
import {
  Card,
  CardHeader,
  Button,
  NodeStatusBadge,
  CardSkeleton,
  AlertBanner,
} from '../design-system';
import { FreshnessIndicator } from '../components/FreshnessIndicator';

interface NodesViewProps {
  nodeList: NodeList | null;
  loading: boolean;
  error: Error | null;
  onSelectNode: (node: Node) => void;
  onSelectTaskId?: (taskId: string) => void;
  onRetry: () => void;
}

const preview = (text: string) => Array.from(text).length > 80 ? Array.from(text).slice(0, 80).join('') + '…' : text;
const time = (value: string | null) => value ? new Date(value).toLocaleString() : '未知';
const commandStatus = (status: string | null) => status === 'cancelled' ? '已撤销' : status || '未知';

export const NodesView: React.FC<NodesViewProps> = ({
  nodeList,
  loading,
  error,
  onSelectNode,
  onRetry,
}) => {
  if (loading && !nodeList) {
    return <CardSkeleton count={3} />;
  }

  if (error && !nodeList) {
    return (
      <AlertBanner
        type="error"
        title="获取节点列表失败"
        message={error.message}
        onRetry={onRetry}
      />
    );
  }

  if (!nodeList) return null;

  const nodeRoles: Record<string, { role: string; desc: string }> = {
    'node-1': {
      role: '研究与深度报告',
      desc: '专职研报、长文交付，通过 GitHub Issue (T-xxx) 闭环',
    },
    'node-2': {
      role: '长流程浏览器任务',
      desc: '负责长流程网页交互、爬取、UI 前端测试与验证',
    },
    'node-3': {
      role: '独立核查与收据出具',
      desc: '独立复核远端 Commit 与交付证据，签发 PASS/REJECT 收据',
    },
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-100 flex items-center gap-2">
            <Server className="h-6 w-6 text-indigo-400" />
            节点集群管理 (Node Management)
          </h2>
          <p className="text-xs text-slate-400 mt-1">
            严格限制 3 个工作节点（node-1/node-2/node-3），具备与总控等同的完整自主判断力
          </p>
        </div>

        <FreshnessIndicator sourceSnapshot={nodeList.source_meta} compact />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {nodeList.items.map((node) => {
          const roleInfo = nodeRoles[node.id] || { role: '通用协同节点', desc: 'Muse 协同节点' };

          return (
            <Card key={node.id} glow={node.status === 'active'} className="flex flex-col justify-between">
              <div>
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <span className="font-mono text-xl font-black text-slate-100 flex items-center gap-2">
                      <Cpu className="h-5 w-5 text-indigo-400" />
                      {node.id}
                    </span>
                    <span className="text-xs font-semibold text-indigo-300 block mt-0.5">
                      {roleInfo.role}
                    </span>
                  </div>
                  <NodeStatusBadge status={node.status} size="md" />
                </div>

                <p className="text-xs text-slate-400 mb-4 leading-relaxed">
                  {roleInfo.desc}
                </p>

                <div className="space-y-2.5 pt-3 border-t border-slate-800/80 text-xs">
                  <div className="flex items-center justify-between">
                    <span className="text-slate-400">最近一次任务号:</span>
                    <span className="font-mono text-indigo-300">{node.last_task_id || '无记录'}</span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-slate-400">最近提交时间:</span>
                    <span className="font-mono text-slate-300">
                      {node.last_commit_at ? new Date(node.last_commit_at).toLocaleString() : '无记录'}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-slate-400">活跃度来源:</span>
                    <span className="font-mono text-slate-300">
                      Git 提交署名前缀
                    </span>
                  </div>
                  <div className="text-slate-300 break-words">
                    <span className="text-slate-400">最近一次指令: </span>
                    {node.last_command?.source_meta.freshness === 'unavailable' ? '来源不可用' : !node.last_command?.id ? '暂无' : <>
                      {node.last_command.id} · {node.last_command.action || '未知'} · {node.last_command.created_by || '未知'} · {time(node.last_command.at)} · {commandStatus(node.last_command.status)}
                      {node.last_command.detail && <> · <span title={node.last_command.detail}>{preview(node.last_command.detail)}</span></>}
                    </>}
                  </div>
                  <div className="text-slate-300 break-words">
                    <span className="text-slate-400">最近一次桥发: </span>
                    {node.last_bridge_send?.source_meta.freshness === 'unavailable' ? '来源不可用' : !node.last_bridge_send?.task_id && !node.last_bridge_send?.status ? '暂无' : <>
                      {node.last_bridge_send.task_id || '未知'} · {time(node.last_bridge_send.sent_at)} · {node.last_bridge_send.status || '未知'}
                      {(node.last_bridge_send.error || node.last_bridge_send.reply) && <> · <span title={node.last_bridge_send.error || node.last_bridge_send.reply || ''}>{preview(node.last_bridge_send.error || node.last_bridge_send.reply || '')}</span></>}
                    </>}
                  </div>
                </div>
              </div>

              <div className="pt-4 mt-4 border-t border-slate-800/60 flex items-center justify-between">
                <span className="text-[10px] font-mono text-slate-500 truncate max-w-[140px]">
                  Ref: {node.source_meta.source_ref}
                </span>
                <Button size="sm" variant="outline" onClick={() => onSelectNode(node)}>
                  深入核查
                </Button>
              </div>
            </Card>
          );
        })}
      </div>

      <Card>
        <CardHeader
          title="节点自治与总控自维护机制 (AGENTS.md 准则)"
          description="系统内部出现故障，总控主动维护，不等用户问、不等人报"
        />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-xs text-slate-300">
          <div className="p-3 rounded-lg border border-slate-800 bg-slate-950/40 space-y-1">
            <span className="font-bold text-slate-100 block">1. 核实故障点</span>
            <p className="text-slate-400">
              与节点直接沟通确认，让节点跑命令核查本机状态，用远端 Git 状态与 Issue 交叉核对。
            </p>
          </div>
          <div className="p-3 rounded-lg border border-slate-800 bg-slate-950/40 space-y-1">
            <span className="font-bold text-slate-100 block">2. 修复即任务</span>
            <p className="text-slate-400">
              故障确认后立项走标准任务书流程（T-xxx），小修也不例外，杜绝口头私下修复。
            </p>
          </div>
          <div className="p-3 rounded-lg border border-slate-800 bg-slate-950/40 space-y-1">
            <span className="font-bold text-slate-100 block">3. 验证闭环与记账</span>
            <p className="text-slate-400">
              修复后按验收标准闭环（收据 + BOARD + MUSE-ACK），修完不验等于没修。
            </p>
          </div>
        </div>
      </Card>
    </div>
  );
};
