import React from 'react';

interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  className?: string;
  glow?: boolean;
}

export const Card: React.FC<CardProps> = ({ children, className = '', glow = false, ...props }) => {
  return (
    <div
      className={`rounded-xl border border-slate-800/90 bg-slate-900/60 backdrop-blur-md p-5 shadow-lg transition-all duration-200 ${
        glow ? 'border-indigo-500/30 shadow-indigo-500/5' : 'hover:border-slate-700/80'
      } ${className}`}
      {...props}
    >
      {children}
    </div>
  );
};

export const CardHeader: React.FC<{
  title: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  className?: string;
}> = ({ title, description, action, className = '' }) => {
  return (
    <div className={`flex flex-wrap sm:flex-nowrap items-start justify-between gap-4 mb-4 ${className}`}>
      <div className="min-w-0">
        <h3 className="text-base font-semibold text-slate-100 tracking-tight flex items-center gap-2">
          {title}
        </h3>
        {description && <p className="text-xs text-slate-400 mt-1">{description}</p>}
      </div>
      {action && <div className="shrink-0">{action}</div>}
    </div>
  );
};
