import type {
  Overview,
  Task,
  Node,
  Runtime,
  RuntimeMonitor,
  RuntimeVerify,
  RuntimeAlerts,
  Note,
  NoteCreate,
  NotePatch,
  Todo,
  TodoCreate,
  TodoPatch,
  NodeList,
  TaskList,
  EventList,
  NoteList,
  TodoList,
  RefreshResult,
  Health,
  ApiError,
  ErrorCode,
  operations,
} from '../types';
import { CustomApiError } from './errors';
import { SnapshotSource } from './snapshot';

export { CustomApiError } from './errors';

export class ApiClient {
  private baseUrl: string = '';
  private accessKey: string | null;
  private snapshot: SnapshotSource | null;
  readonly staticMode: boolean;

  constructor({ staticMode = import.meta.env?.VITE_STATIC_MODE === 'true' }: { staticMode?: boolean } = {}) {
    this.staticMode = staticMode;
    this.snapshot = staticMode ? new SnapshotSource() : null;
    this.accessKey = staticMode ? null : import.meta.env?.VITE_CT_ACCESS_KEY || null;

    this.getOverview = this.getOverview.bind(this);
    this.listNodes = this.listNodes.bind(this);
    this.getNode = this.getNode.bind(this);
    this.listTasks = this.listTasks.bind(this);
    this.getTask = this.getTask.bind(this);
    this.listEvents = this.listEvents.bind(this);
    this.getRuntime = this.getRuntime.bind(this);
    this.listNotes = this.listNotes.bind(this);
    this.createNote = this.createNote.bind(this);
    this.patchNote = this.patchNote.bind(this);
    this.deleteNote = this.deleteNote.bind(this);
    this.listTodos = this.listTodos.bind(this);
    this.createTodo = this.createTodo.bind(this);
    this.patchTodo = this.patchTodo.bind(this);
    this.deleteTodo = this.deleteTodo.bind(this);
    this.refreshReadModels = this.refreshReadModels.bind(this);
    this.healthz = this.healthz.bind(this);
  }

  setAccessKey(key: string | null) {
    this.accessKey = this.staticMode ? null : key;
  }

  getAccessKey(): string | null {
    return this.accessKey;
  }

  setBaseUrl(url: string) {
    this.baseUrl = url.replace(/\/$/, '');
  }

  getBaseUrl(): string {
    return this.baseUrl;
  }

  get snapshotRefreshedAt(): string | null {
    return this.snapshot?.refreshedAt ?? null;
  }

  get snapshotPendingDecisions() {
    return this.snapshot?.pendingDecisions;
  }

  private async request<T>(path: string, options: RequestInit = {}): Promise<T> {
    if (this.snapshot) return this.snapshot.request<T>(path, options);

    const headers: Record<string, string> = {
      Accept: 'application/json',
      ...(options.headers as Record<string, string>),
    };

    if (options.body) {
      headers['Content-Type'] = 'application/json';
    }

    if (this.accessKey) {
      headers['X-CT-Access-Key'] = this.accessKey;
    }

    // Ensure non-browser clients (e.g. Node/Bun test environments) supply an allowed Origin for mutations
    const method = (options.method || 'GET').toUpperCase();
    if (['POST', 'PATCH', 'DELETE'].includes(method)) {
      if (!headers['Origin'] && typeof window === 'undefined') {
        headers['Origin'] = 'http://127.0.0.1:3000';
      }
    }

    const url = `${this.baseUrl}${path}`;
    const response = await fetch(url, {
      ...options,
      headers,
    });

    if (response.status === 204) {
      return undefined as unknown as T;
    }

    let body: unknown;
    try {
      body = await response.json();
    } catch {
      body = null;
    }

    if (!response.ok) {
      if (body && typeof body === 'object' && 'code' in body && 'message' in body) {
        const apiErr = body as ApiError;
        throw new CustomApiError(apiErr.code, apiErr.message, response.status);
      }
      const defaultCode: ErrorCode =
        response.status === 401
          ? 'AUTH_REQUIRED'
          : response.status === 403
          ? 'FORBIDDEN_ORIGIN'
          : response.status === 404
          ? 'NOT_FOUND'
          : response.status === 409
          ? 'REFRESH_IN_PROGRESS'
          : response.status === 422
          ? 'VALIDATION_ERROR'
          : response.status === 429
          ? 'GITHUB_RATE_LIMITED'
          : response.status === 503
          ? 'SOURCE_UNAVAILABLE'
          : 'INTERNAL_ERROR';
      throw new CustomApiError(
        defaultCode,
        response.statusText || `Request failed with status ${response.status}`,
        response.status
      );
    }

    return body as T;
  }

  getOverview(): Promise<Overview> {
    return this.request<Overview>('/api/v1/overview');
  }

  listNodes(): Promise<NodeList> {
    return this.request<NodeList>('/api/v1/nodes');
  }

  getNode(nodeId: string): Promise<Node> {
    return this.request<Node>(`/api/v1/nodes/${encodeURIComponent(nodeId)}`);
  }

  listTasks(params?: operations['listTasks']['parameters']['query']): Promise<TaskList> {
    const search = new URLSearchParams();
    if (params?.q) search.set('q', params.q);
    if (params?.status) search.set('status', params.status);
    if (params?.assignee) search.set('assignee', params.assignee);
    if (params?.limit !== undefined) search.set('limit', String(params.limit));
    if (params?.offset !== undefined) search.set('offset', String(params.offset));
    const qs = search.toString();
    return this.request<TaskList>(`/api/v1/tasks${qs ? `?${qs}` : ''}`);
  }

  getTask(taskId: string): Promise<Task> {
    return this.request<Task>(`/api/v1/tasks/${encodeURIComponent(taskId)}`);
  }

  listEvents(params?: operations['listEvents']['parameters']['query']): Promise<EventList> {
    const search = new URLSearchParams();
    if (params?.node_id) search.set('node_id', params.node_id);
    if (params?.task_id) search.set('task_id', params.task_id);
    if (params?.limit !== undefined) search.set('limit', String(params.limit));
    if (params?.offset !== undefined) search.set('offset', String(params.offset));
    const qs = search.toString();
    return this.request<EventList>(`/api/v1/events${qs ? `?${qs}` : ''}`);
  }

  getRuntime(): Promise<Runtime> {
    return this.request<Runtime>('/api/v1/runtime');
  }

  getRuntimeVerify(): Promise<RuntimeVerify> {
    return this.request<RuntimeVerify>('/api/v1/runtime/verify');
  }

  getRuntimeMonitor(): Promise<RuntimeMonitor> {
    return this.request<RuntimeMonitor>('/api/v1/runtime/monitor');
  }

  getRuntimeAlerts(): Promise<RuntimeAlerts | null> {
    return this.request<RuntimeAlerts | null>('/api/v1/runtime/alerts');
  }

  listNotes(): Promise<NoteList> {
    return this.request<NoteList>('/api/v1/notes');
  }

  createNote(data: NoteCreate): Promise<Note> {
    return this.request<Note>('/api/v1/notes', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  patchNote(id: string, data: NotePatch): Promise<Note> {
    return this.request<Note>(`/api/v1/notes/${encodeURIComponent(id)}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  }

  deleteNote(id: string): Promise<void> {
    return this.request<void>(`/api/v1/notes/${encodeURIComponent(id)}`, {
      method: 'DELETE',
    });
  }

  listTodos(): Promise<TodoList> {
    return this.request<TodoList>('/api/v1/todos');
  }

  createTodo(data: TodoCreate): Promise<Todo> {
    return this.request<Todo>('/api/v1/todos', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  patchTodo(id: string, data: TodoPatch): Promise<Todo> {
    return this.request<Todo>(`/api/v1/todos/${encodeURIComponent(id)}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  }

  deleteTodo(id: string): Promise<void> {
    return this.request<void>(`/api/v1/todos/${encodeURIComponent(id)}`, {
      method: 'DELETE',
    });
  }

  refreshReadModels(): Promise<RefreshResult> {
    return this.request<RefreshResult>('/api/v1/refresh', {
      method: 'POST',
    });
  }

  healthz(): Promise<Health> {
    return this.request<Health>('/healthz');
  }
}

export const apiClient = new ApiClient();
