export const REFRESH_INTERVAL_MS = 60_000;

// Keep one collection in flight even when GitHub takes longer than a cycle.
export function startAutoRefresh(refresh: () => Promise<void>) {
  let running = false;
  let stopped = false;
  const tick = async () => {
    if (running || stopped) return;
    running = true;
    try {
      await refresh();
    } finally {
      running = false;
    }
  };
  void tick();
  const timer = setInterval(() => void tick(), REFRESH_INTERVAL_MS);
  return () => { stopped = true; clearInterval(timer); };
}
