import type {
  Overview, NodeList, TaskList, EventList, Runtime, NoteList, TodoList,
  DerivedStatus, RuntimeAlerts, VerifyResult,
} from '../types';
import { CustomApiError } from './errors';

export interface PendingDecision {
  title: string;
  consequence: string;
}

export interface TowerSnapshot {
  refreshed_at: string;
  overview: Overview;
  nodes: NodeList;
  tasks: TaskList;
  events: EventList;
  runtime: Runtime;
  alerts?: RuntimeAlerts;
  verify?: VerifyResult | null;
  pending_decisions?: PendingDecision[];
  notes: NoteList;
  todos: TodoList;
}

const statuses: Set<DerivedStatus> = new Set([
  'pending', 'in_progress', 'pending_review', 'delivered', 'accepted', 'rejected',
  'failed', 'checkpointed', 'resuming', 'parked', 'needs_attention', 'unverified',
  'unknown', 'unlisted',
]);
const nodeIds = new Set(['node-1', 'node-2', 'node-3']);

function validateSnapshot(value: unknown): TowerSnapshot {
  const data = value as TowerSnapshot | null;
  if (!data || typeof data.refreshed_at !== 'string' ||
      !Number.isFinite(Date.parse(data.refreshed_at)) ||
      !data.overview?.task_counts || !Array.isArray(data.overview.nodes) ||
      !data.runtime?.refresh_meta ||
      ![data.nodes, data.tasks, data.events, data.notes, data.todos].every(
        list => list && Array.isArray(list.items) && Number.isInteger(list.total) && list.total >= 0
      )) {
    throw new Error('快照格式无效');
  }
  return data;
}

function paginate<T>(
  list: { items: T[]; total: number }, params: URLSearchParams, matches?: (item: T) => boolean,
) {
  const limit = Number(params.get('limit') ?? 50);
  const offset = Number(params.get('offset') ?? 0);
  if (!Number.isInteger(limit) || limit < 1 || limit > 100 ||
      !Number.isInteger(offset) || offset < 0) {
    throw new CustomApiError('VALIDATION_ERROR', 'Request validation failed', 422);
  }
  const items = matches ? list.items.filter(matches) : list.items;
  return {
    ...list,
    items: items.slice(offset, offset + limit),
    // Preserve the endpoint's total when the export contains only its first page.
    total: matches ? items.length : list.total,
  };
}

export class SnapshotSource {
  private pending: Promise<TowerSnapshot> | null = null;
  refreshedAt: string | null = null;
  pendingDecisions: PendingDecision[] | undefined;

  private load(): Promise<TowerSnapshot> {
    if (!this.pending) {
      this.pending = (async () => {
        try {
          const response = await fetch('./snapshot.json', { credentials: 'omit', cache: 'no-store' });
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          const snapshot = validateSnapshot(await response.json());
          this.refreshedAt = snapshot.refreshed_at;
          this.pendingDecisions = snapshot.pending_decisions;
          return snapshot;
        } catch (error) {
          this.pending = null;
          throw new CustomApiError('SOURCE_UNAVAILABLE',
            `无法加载 ./snapshot.json：${error instanceof Error ? error.message : '读取失败'}`, 503);
        }
      })();
    }
    return this.pending;
  }

  async request<T>(path: string, options: RequestInit): Promise<T> {
    if ((options.method ?? 'GET').toUpperCase() !== 'GET') {
      throw new CustomApiError('SOURCE_UNAVAILABLE', '静态模式不可用：快照只读，无法写入或全量同步。', 503);
    }
    const data = await this.load();
    const [pathname, query] = path.split('?');
    const params = new URLSearchParams(query);
    let result: unknown;
    switch (pathname) {
      case '/api/v1/overview': result = data.overview; break;
      case '/api/v1/nodes': result = data.nodes; break;
      case '/api/v1/tasks': {
        const q = params.get('q')?.toLowerCase();
        const status = params.get('status');
        const assignee = params.get('assignee');
        if ((status && !statuses.has(status as DerivedStatus)) || (assignee && !nodeIds.has(assignee))) {
          throw new CustomApiError('VALIDATION_ERROR', 'Request validation failed', 422);
        }
        result = paginate(data.tasks, params, q || status || assignee ? task => {
          return (!q || task.id.toLowerCase().includes(q) || task.title.toLowerCase().includes(q)) &&
            (!status || task.derived_status === status) && (!assignee || task.assignee === assignee);
        } : undefined);
        break;
      }
      case '/api/v1/events': {
        const nodeId = params.get('node_id');
        const taskId = params.get('task_id');
        if (nodeId && !nodeIds.has(nodeId)) {
          throw new CustomApiError('VALIDATION_ERROR', 'Request validation failed', 422);
        }
        result = paginate(data.events, params, nodeId || taskId ? event => {
          return (!nodeId || event.node_id === nodeId) && (!taskId || event.task_id === taskId);
        } : undefined);
        break;
      }
      case '/api/v1/runtime': result = data.runtime; break;
      case '/api/v1/runtime/verify': result = data.verify ? { verify: data.verify, source_meta: { status: 'available' } } : { verify: null, source_meta: { status: 'unavailable', reason: 'missing' } }; break;
      case '/api/v1/runtime/alerts': result = data.alerts ?? null; break;
      case '/api/v1/notes': result = data.notes; break;
      case '/api/v1/todos': result = data.todos; break;
      // This reports that the local snapshot loaded, not live backend liveness.
      case '/healthz': result = { status: 'ok' }; break;
      default:
        if (pathname.startsWith('/api/v1/nodes/')) {
          result = data.nodes.items.find(node => node.id === decodeURIComponent(pathname.slice('/api/v1/nodes/'.length)));
        } else if (pathname.startsWith('/api/v1/tasks/')) {
          result = data.tasks.items.find(task => task.id === decodeURIComponent(pathname.slice('/api/v1/tasks/'.length)));
        }
        if (!result) throw new CustomApiError('NOT_FOUND', 'Resource not found', 404);
    }
    // Callers cannot mutate the shared in-memory snapshot.
    return structuredClone(result) as T;
  }
}
