import React from 'react';
import {
  Server,
  Layers,
  Radio,
  Clock,
  ArrowRight,
  Terminal,
} from 'lucide-react';
import type { Overview, Task, Node, Event } from '../types';
import type { PendingDecision } from '../api/snapshot';
import {
  Card,
  CardHeader,
  Button,
  NodeStatusBadge,
  SeverityBadge,
  EventStateBadge,
  DERIVED_STATUS_CONFIG,
  CardSkeleton,
  AlertBanner,
} from '../design-system';
import { FreshnessIndicator } from '../components/FreshnessIndicator';

interface OverviewViewProps {
  overview: Overview | null;
  loading: boolean;
  error: Error | null;
  staticMode?: boolean;
  snapshotTime?: string | null;
  pendingDecisions?: PendingDecision[];
  onNavigateTab: (tab: 'nodes' | 'tasks' | 'runtime' | 'notes-todos' | 'events') => void;
  onSelectTask: (task: Task) => void;
  onSelectNode: (node: Node) => void;
  onSelectEvent: (event: Event) => void;
  onRetry: () => void;
}

export const OverviewView: React.FC<OverviewViewProps> = ({
  overview,
  loading,
  error,
  staticMode = false,
  snapshotTime,
  pendingDecisions,
  onNavigateTab,
  onSelectTask,
  onSelectNode,
  onSelectEvent,
  onRetry,
}) => {
  if (loading && !overview) {
    return (
      <div className="space-y-6">
        <CardSkeleton count={3} />
        <CardSkeleton count={4} />
      </div>
    );
  }

  if (error && !overview) {
    return (
      <AlertBanner
        type="error"
        title="加载总览数据失败"
        message={error.message}
        onRetry={onRetry}
      />
    );
  }

  if (!overview) return null;

  const { nodes, task_counts, recent_events, runtime, source_meta } = overview;

  // Only BOARD states are displayed; legacy API count keys remain zero.
  const countKeys: (keyof Overview['task_counts'])[] = [
    'pending',
    'in_progress',
    'pending_review',
    'accepted',
    'rejected',
    'failed',
  ];

  return (
    <div className="space-y-6">
      {/* Freshness Snapshot Banner */}
      <FreshnessIndicator sourceSnapshot={source_meta} />

      {pendingDecisions !== undefined && (
        <Card>
          <CardHeader title="待 Chen 决策" />
          <ul className="space-y-4">
            {pendingDecisions.map((decision, index) => (
              <li key={index} className="min-w-0 break-words">
                <p className="font-medium text-slate-100">{decision.title}</p>
                <p className="mt-1 text-sm text-slate-400">不做会怎样：{decision.consequence}</p>
              </li>
            ))}
          </ul>
        </Card>
      )}

      <Card>
        <CardHeader title="一致性校验" />
        {staticMode && <p className="text-xs text-slate-400">快照时间：{snapshotTime ?? '未知'}</p>}
        {overview.reconciliation ? (
          <div className={overview.reconciliation.match ? 'text-emerald-400' : 'text-red-400'}>
            <p className="break-words">{overview.reconciliation.match ? '一致' : '不一致'} · BOARD {overview.reconciliation.board_total} 行 · 页面 {overview.reconciliation.tasks_total} 条 · BOARD HEAD {overview.reconciliation.board_head ?? '未知'} · 比对时间 {overview.reconciliation.checked_at}</p>
            {overview.reconciliation.diffs.map((diff, index) => <p key={index} className="break-words">{diff}</p>)}
          </div>
        ) : <p className="text-slate-400">{staticMode ? '快照未含对账数据' : '暂无对账数据'}</p>}
      </Card>

      {/* Partial / Degraded Alert if partial=true */}
      {source_meta.partial && (
        <AlertBanner
          type="partial"
          title="数据处于降级状态 (partial=true)"
          message="由于部分来源不可用或为旧缓存快照，当前总览仅统计可用数据，请勿视为全量最新生产事实。"
        />
      )}

      {/* BOARD task counts */}
      <Card glow>
        <CardHeader
          title={
            <div className="flex items-center gap-2">
              <Layers className="h-5 w-5 text-indigo-400" />
              <span>任务状态（BOARD）</span>
            </div>
          }
          description="状态直接映射 BOARD，统计包含全部 BOARD 行；unlisted 单列且不计入统计。"
          action={
            <Button
              size="sm"
              variant="outline"
              onClick={() => onNavigateTab('tasks')}
              className="text-xs"
            >
              进入任务中心 <ArrowRight className="h-3 w-3 ml-1" />
            </Button>
          }
        />

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-7 gap-3 pt-1">
          {countKeys.map((statusKey) => {
            const config = DERIVED_STATUS_CONFIG[statusKey];
            const count = task_counts[statusKey] ?? 0;

            return (
              <div
                key={statusKey}
                onClick={() => onNavigateTab('tasks')}
                className={`p-3 rounded-xl border ${config.border} ${config.bg} cursor-pointer hover:scale-[1.02] transition-transform flex flex-col justify-between`}
              >
                <div className="flex items-center justify-between">
                  <span className={`h-2 w-2 rounded-full ${config.dot}`} />
                  <span className="font-mono text-xl font-black text-slate-100">{count}</span>
                </div>
                <div className="mt-2">
                  <div className={`text-xs font-semibold ${config.text} truncate`}>
                    {config.shortLabel}
                  </div>
                  <div className="text-[10px] text-slate-400 truncate" title={config.description}>
                    {config.label.split(' ')[0]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </Card>

      <Card>
        <CardHeader title={`BOARD 外任务 · unlisted（${overview.unlisted_tasks.length}）`}
          description="以下任务未在 BOARD 登记，不计入上方统计。" />
        {overview.unlisted_tasks.map(task => (
          <button key={task.id} onClick={() => onSelectTask(task)} className="block text-left break-words text-sm text-yellow-400 py-1">
            {task.id} · {task.title} · unlisted
          </button>
        ))}
      </Card>

      {/* Grid: Nodes Summary & Runtime Quick Look */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Nodes Management Summary */}
        <div className="lg:col-span-2 space-y-4">
          <Card>
            <CardHeader
              title={
                <div className="flex items-center gap-2">
                  <Server className="h-5 w-5 text-indigo-400" />
                  <span>集群节点运行态 (Node Management)</span>
                </div>
              }
              description="固定 3 节点布局（node-1 研究 / node-2 浏览器 / node-3 核查），无虚构 node-4"
              action={
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => onNavigateTab('nodes')}
                  className="text-xs"
                >
                  管理节点 <ArrowRight className="h-3 w-3 ml-1" />
                </Button>
              }
            />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {nodes.map((node) => (
                <div
                  key={node.id}
                  onClick={() => onSelectNode(node)}
                  className="p-4 rounded-xl border border-slate-800 bg-slate-950/60 hover:border-indigo-500/50 transition-all cursor-pointer space-y-3"
                >
                  <div className="flex items-center justify-between">
                    <span className="font-mono font-bold text-slate-100">{node.id}</span>
                    <NodeStatusBadge status={node.status} size="sm" />
                  </div>

                  <div className="space-y-1 text-xs">
                    <div className="text-slate-400">最近一次任务号:</div>
                    <div className="font-mono text-indigo-300 font-semibold truncate">
                      {node.last_task_id || '无记录'}
                    </div>
                  </div>

                  <div className="pt-2 border-t border-slate-800/80 text-[10px] text-slate-400 flex items-center justify-between">
                    <span>最近提交:</span>
                    <span className="font-mono text-slate-300">
                      {node.last_commit_at ? new Date(node.last_commit_at).toLocaleString() : '无记录'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </Card>
        </div>

        {/* Dual Patrol & Health Widget */}
        <div className="space-y-4">
          <Card>
            <CardHeader
              title={
                <div className="flex items-center gap-2">
                  <Radio className="h-5 w-5 text-indigo-400" />
                  <span>双侧巡逻监控</span>
                </div>
              }
              description="节点 300s vs 总控 60s 独立读取 (CH-11)"
              action={
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => onNavigateTab('runtime')}
                  className="text-xs"
                >
                  详情
                </Button>
              }
            />

            <div className="space-y-3 text-xs">
              <div className="p-3 rounded-lg border border-slate-800 bg-slate-950/50 space-y-1">
                <div className="flex items-center justify-between font-mono font-semibold text-slate-300">
                  <span>节点侧巡逻 (patrol.sh)</span>
                  <span className="text-emerald-400 font-bold">
                    {runtime.node_patrol.interval_seconds}s
                  </span>
                </div>
                <div className="text-[11px] text-slate-400 flex justify-between">
                  <span>源: {runtime.node_patrol.source}</span>
                  <span className="text-emerald-400 uppercase">{runtime.node_patrol.status}</span>
                </div>
              </div>

              <div className="p-3 rounded-lg border border-slate-800 bg-slate-950/50 space-y-1">
                <div className="flex items-center justify-between font-mono font-semibold text-slate-300">
                  <span>总控侧巡逻 (Hook Poll)</span>
                  <span className="text-indigo-400 font-bold">
                    {runtime.director_patrol.interval_seconds}s
                  </span>
                </div>
                <div className="text-[11px] text-slate-400 flex justify-between">
                  <span>源: {runtime.director_patrol.source}</span>
                  <span className="text-emerald-400 uppercase">{runtime.director_patrol.status}</span>
                </div>
              </div>

              <div className="p-2.5 rounded-lg bg-black/40 border border-slate-800/80 text-[11px] text-slate-400 flex items-center gap-2">
                <Clock className="h-4 w-4 text-slate-500 shrink-0" />
                <span>
                  实时保证: <strong>false</strong> (不保证绝对实时，非故障断言)
                </span>
              </div>
            </div>
          </Card>
        </div>
      </div>

      {/* Recent Events List */}
      <Card>
        <CardHeader
          title={
            <div className="flex items-center gap-2">
              <Terminal className="h-5 w-5 text-indigo-400" />
              <span>最近事件流水 (Recent Events Stream)</span>
            </div>
          }
          description="按检测时间降序排列，包含 ACKED、NEEDS_ATTENTION 与 NEEDS_RECONCILIATION"
          action={
            <Button
              size="sm"
              variant="outline"
              onClick={() => onNavigateTab('events')}
              className="text-xs"
            >
              查看全量事件 <ArrowRight className="h-3 w-3 ml-1" />
            </Button>
          }
        />

        <div className="space-y-2">
          {recent_events.length === 0 ? (
            <div className="p-4 text-center text-xs text-slate-500 font-mono">暂无事件记录</div>
          ) : (
            recent_events.slice(0, 4).map((evt) => (
              <div
                key={evt.id}
                onClick={() => onSelectEvent(evt)}
                className="p-3 rounded-xl border border-slate-800/80 bg-slate-950/40 hover:bg-slate-900/60 transition-colors cursor-pointer flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2"
              >
                <div className="flex flex-wrap sm:flex-nowrap items-center gap-3 min-w-0">
                  <SeverityBadge severity={evt.severity} />
                  <span className="font-mono font-bold text-xs text-slate-200 break-all">{evt.id}</span>
                  <span className="text-xs text-slate-300 line-clamp-1">{evt.summary}</span>
                </div>
                <div className="flex items-center gap-2 shrink-0 self-end sm:self-center">
                  <EventStateBadge state={evt.state} size="sm" />
                  <span className="font-mono text-[11px] text-slate-400">
                    {evt.timestamps.detected_at
                      ? new Date(evt.timestamps.detected_at).toLocaleTimeString()
                      : '-'}
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      </Card>
    </div>
  );
};
