import { useCallback, useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { Send } from 'lucide-react';
import { api } from '../api';
import { COMMAND_UNAVAILABLE, listCommands, submitCommand } from '../api/commands';
import type { CommandEntry, CommandLists, CommandRequest, CommandTarget } from '../api/commands';
import type { Task } from '../types';
import { AlertBanner, Button, Card, CardHeader, Input, Select } from '../design-system';

const nodes = ['node-1', 'node-2', 'node-3'].map(value => ({ value, label: value }));
const statuses = ['完成', '进行中', '待领', '拒收'].map(value => ({ value, label: value }));
const textareaClass = 'w-full bg-slate-900 border border-slate-700 rounded-lg text-slate-100 text-sm p-3 focus:outline-none focus:border-indigo-500';

const commandTemplates = [
  { label: '催节点更新进度', action: 'notify_node', text: '请更新 T-___ 的最新进度（做了什么、下一步、是否卡住）' },
  { label: '催节点认领', action: 'notify_node', text: 'T-___ 已派发，请确认认领并给出预计完成时间' },
  { label: '查任务状态', action: 'query', text: 'T-___ 当前状态是什么？最后一次提交和验收情况如何？' },
  { label: '查节点最近动态', action: 'query', text: 'node-___ 最近一次提交是什么时候？在做什么任务？' },
] as const;

type Template = typeof commandTemplates[number];
type MessageFields = { node: string; message: string; question: string };

export function templateFields(template: Template): MessageFields {
  return { node: '', message: template.action === 'notify_node' ? template.text : '', question: template.action === 'query' ? template.text : '' };
}

export function commandIsComplete(command: CommandRequest): boolean {
  return Object.values(command.payload).every(value => value.trim());
}

export function CommandMessageForms({ fields, onFieldsChange, onSubmit, disabled, staticMode }: {
  fields: MessageFields; onFieldsChange: (fields: MessageFields) => void;
  onSubmit: (event: FormEvent<HTMLFormElement>, action: 'notify_node' | 'query') => void; disabled: boolean; staticMode: boolean;
}) {
  return <>
    {!staticMode && <div className="xl:col-span-3 flex flex-wrap items-center gap-2" aria-label="指令模板">
      <span className="text-sm text-slate-400">指令模板</span>
      {commandTemplates.map(template => <Button key={template.label} type="button" onClick={() => onFieldsChange(templateFields(template))}>{template.label}</Button>)}
    </div>}
    <Card>
      <CardHeader title="发消息" />
      <form aria-label="发消息" className="space-y-4" onSubmit={event => onSubmit(event, 'notify_node')}>
        <Select label="目标节点" id="command-node" name="node" required value={fields.node}
          onChange={event => onFieldsChange({ ...fields, node: event.target.value })}
          options={[{ value: '', label: '请选择节点' }, ...nodes]} />
        <div>
          <label htmlFor="command-message" className="block text-xs font-medium text-slate-300 mb-1.5">消息内容</label>
          <textarea id="command-message" name="message" rows={5} required className={textareaClass} value={fields.message}
            onChange={event => onFieldsChange({ ...fields, message: event.target.value })} />
        </div>
        <Button type="submit" variant="primary" disabled={disabled}>提交发消息指令</Button>
      </form>
    </Card>
    <Card>
      <CardHeader title="问问题" />
      <form aria-label="问问题" className="space-y-4" onSubmit={event => onSubmit(event, 'query')}>
        <div>
          <label htmlFor="command-question" className="block text-xs font-medium text-slate-300 mb-1.5">问题</label>
          <textarea id="command-question" name="question" rows={5} required className={textareaClass} value={fields.question}
            onChange={event => onFieldsChange({ ...fields, question: event.target.value })} />
        </div>
        <Button type="submit" variant="primary" disabled={disabled}>提交问题</Button>
      </form>
    </Card>
  </>;
}

export function CommandTable({ entries, pending, staticMode, confirmingId, disabled, onCancel }: {
  entries: CommandEntry[]; pending: boolean; staticMode: boolean; confirmingId: string | null;
  disabled: boolean; onCancel: (id: string) => void;
}) {
  if (entries.length === 0) return <p className="text-sm text-slate-400">暂无{pending ? '待处理' : '已处理'}指令</p>;
  return (
    <div className="overflow-x-auto">
      <table className="block sm:table w-full text-left text-xs">
        <thead className="hidden sm:table-header-group text-slate-400 border-b border-slate-700">
          <tr>{['指令 ID', 'action', 'target', '创建时间', '结果状态'].map(label => (
            <th key={label} scope="col" className="p-2 whitespace-nowrap">{label}</th>
          ))}{pending && !staticMode && <th scope="col" className="p-2">操作</th>}</tr>
        </thead>
        <tbody className="block sm:table-row-group">
          {entries.map(entry => (
            <tr key={entry.id} className="block sm:table-row border-b border-slate-800 py-2 sm:py-0">
              <td className="block sm:table-cell p-2 font-mono break-all sm:whitespace-nowrap before:content-['指令_ID:_'] sm:before:content-none before:text-slate-400">{entry.id}</td>
              <td className="block sm:table-cell p-2 break-words before:content-['action:_'] sm:before:content-none before:text-slate-400">{entry.action}</td>
              <td className="block sm:table-cell p-2 break-words before:content-['target:_'] sm:before:content-none before:text-slate-400">{entry.target}</td>
              <td className="block sm:table-cell p-2 break-all sm:whitespace-nowrap before:content-['创建时间:_'] sm:before:content-none before:text-slate-400"><time dateTime={entry.created_at}>{entry.created_at}</time></td>
              <td className="block sm:table-cell p-2 break-words">
                <span className="sm:hidden text-slate-400 mr-2">结果状态:</span><span>{pending ? '待处理（pending）' : (entry.result?.status ?? entry.status) === 'cancelled' ? '已撤销' : entry.result?.status ?? entry.status ?? '未返回结果'}</span>
                {pending && entry.result?.detail && <p className="mt-1 text-slate-400">{entry.result.detail}</p>}
                {!pending && <details className="mt-1 text-slate-300">
                  <summary className="cursor-pointer">查看详情</summary>
                  <dl className="mt-2 space-y-1 whitespace-pre-wrap break-all">
                    <div><dt className="inline font-semibold">id: </dt><dd className="inline">{entry.id}</dd></div>
                    {entry.result?.status && <div><dt className="inline font-semibold">status: </dt><dd className="inline">{entry.result.status}</dd></div>}
                    {entry.result?.by && <div><dt className="inline font-semibold">by: </dt><dd className="inline">{entry.result.by}</dd></div>}
                    {entry.result?.at && <div><dt className="inline font-semibold">at: </dt><dd className="inline"><time dateTime={entry.result.at}>{new Date(entry.result.at).toLocaleString()}</time></dd></div>}
                    {entry.result?.detail && <div><dt className="inline font-semibold">detail: </dt><dd className="inline">{entry.result.detail}</dd></div>}
                    {!!entry.result?.artifacts?.filter(Boolean).length && <div><dt className="font-semibold">artifacts:</dt><dd><ul>{entry.result.artifacts.filter(Boolean).map((artifact, index) => <li key={index}>{artifact}</li>)}</ul></dd></div>}
                  </dl>
                </details>}
              </td>
              {pending && !staticMode && <td className="block sm:table-cell p-2">
                <Button type="button" size="sm" disabled={disabled} onClick={() => onCancel(entry.id)}
                  aria-label={`${confirmingId === entry.id ? '确认撤销' : '撤销'} ${entry.id}`}>
                  {confirmingId === entry.id ? '确认撤销' : '撤销'}
                </Button>
              </td>}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// Command polling is independent of the global data refresh cadence.
export function startCommandRefresh(refresh: () => Promise<void>) {
  let running = false;
  let stopped = false;
  const tick = async () => {
    if (running || stopped) return;
    running = true;
    try { await refresh(); } finally { running = false; }
  };
  void tick();
  const timer = setInterval(() => void tick(), 30_000);
  return () => { stopped = true; clearInterval(timer); };
}

export function CommandsView() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [tasksLoading, setTasksLoading] = useState(true);
  const [taskError, setTaskError] = useState<string | null>(null);
  const [commands, setCommands] = useState<CommandLists | null>(null);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [queuedId, setQueuedId] = useState<string | null>(null);
  const [tokenInput, setTokenInput] = useState('');
  const [token, setToken] = useState('');
  const [confirmingId, setConfirmingId] = useState<string | null>(null);
  const [messageFields, setMessageFields] = useState<MessageFields>({ node: 'node-1', message: '', question: '' });

  const loadTasks = useCallback(async () => {
    setTasksLoading(true);
    setTaskError(null);
    try {
      // Keep the command selector independent of the task view's search and filters.
      const items: Task[] = [];
      let total = 0;
      do {
        const page = await api.listTasks({ limit: 100, offset: items.length });
        items.push(...page.items);
        total = page.total;
        // Static exports only contain their exported page, even if total is larger.
        if (api.staticMode || page.items.length === 0) break;
      } while (items.length < total);
      setTasks(items);
    } catch (error) {
      setTasks([]);
      setTaskError(`无法加载任务列表：${error instanceof Error ? error.message : '读取失败'}`);
    } finally {
      setTasksLoading(false);
    }
  }, []);

  const loadCommands = useCallback(async () => {
    if (!token) return;
    setListLoading(true);
    try {
      setCommands(await listCommands(token));
      setListError(null);
    } catch (error) {
      setListError(error instanceof Error ? error.message : COMMAND_UNAVAILABLE);
    } finally {
      setListLoading(false);
    }
  }, [token]);

  useEffect(() => {
    void loadTasks();
  }, [loadTasks]);

  useEffect(() => {
    if (api.staticMode || !token) return;
    return startCommandRefresh(loadCommands);
  }, [loadCommands, token]);

  const sendCommand = async (command: CommandRequest) => {
    setSubmitting(true);
    setSubmitError(null);
    setQueuedId(null);
    try {
      const result = await submitCommand(command, token, api.staticMode);
      setQueuedId(result.id);
      await loadCommands();
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : COMMAND_UNAVAILABLE);
    } finally {
      setSubmitting(false);
    }
  };

  const handleCancel = (id: string) => {
    if (submitting || !token || api.staticMode) return;
    if (confirmingId !== id) {
      setConfirmingId(id);
      return;
    }
    setConfirmingId(null);
    void sendCommand({ action: 'cancel', target: 'total', payload: { cancel_id: id } });
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>, action: Exclude<CommandRequest['action'], 'cancel'>) => {
    event.preventDefault();
    if (submitting || !token) return;
    const fields = new FormData(event.currentTarget);
    const text = (name: string) => String(fields.get(name) ?? '').trim();
    let command: CommandRequest;
    if (action === 'dispatch') {
      const assignee = text('assignee');
      command = {
        action, target: assignee === 'Codex' ? 'total' : assignee as CommandTarget,
        payload: { title: text('title'), assignee, body_markdown: text('body_markdown') },
      };
    } else if (action === 'board_status') {
      command = {
        action, target: 'total',
        payload: { task_id: text('task_id'), status: text('status') as '完成' | '进行中' | '待领' | '拒收' },
      };
    } else if (action === 'notify_node') {
      const node = text('node') as Exclude<CommandTarget, 'total'>;
      command = { action, target: node, payload: { node, message: text('message') } };
    } else {
      command = { action, target: 'total', payload: { question: text('question') } };
    }
    if (!commandIsComplete(command)) {
      setSubmitError('请填写所有必填内容。');
      setQueuedId(null);
      return;
    }
    await sendCommand(command);
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-bold flex items-center gap-2"><Send className="h-6 w-6 text-indigo-400" />指令</h2>
        <p className="text-sm text-slate-400 mt-1">通过本地控制层发送指令，并查看排队和处理结果。</p>
      </div>

      <form className="flex flex-wrap items-end gap-3" onSubmit={event => { event.preventDefault(); setToken(tokenInput.trim()); }}>
        <div className="w-full sm:max-w-sm">
          <Input label="指令 token" id="command-token" type="password" autoComplete="off" value={tokenInput}
            onChange={event => { setTokenInput(event.target.value); setToken(''); setConfirmingId(null); }} />
        </div>
        <Button type="submit">使用指令 token</Button>
        {!token && <p className="text-sm text-yellow-300">请先输入指令 token</p>}
      </form>

      {queuedId && <div role="status" className="break-all rounded-xl border border-emerald-700 bg-emerald-950/40 p-4 text-sm text-emerald-200">
        <span className="font-mono">{queuedId}</span> · 已入队，预计 1–3 分钟被处理
      </div>}
      {submitError && <div role="alert"><AlertBanner type="error" title="指令提交失败" message={submitError} /></div>}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-4 min-w-0">
        <Card>
          <CardHeader title="派任务" />
          <form aria-label="派任务" className="space-y-4" onSubmit={event => handleSubmit(event, 'dispatch')}>
            <Input label="标题" id="command-title" name="title" required />
            <Select label="执行方" id="command-assignee" name="assignee" options={[{ value: 'Codex', label: 'Codex' }, ...nodes]} />
            <div>
              <label htmlFor="command-body" className="block text-xs font-medium text-slate-300 mb-1.5">正文（Markdown）</label>
              <textarea id="command-body" name="body_markdown" rows={5} required className={textareaClass} />
            </div>
            <Button type="submit" variant="primary" disabled={submitting || !token}>提交派任务指令</Button>
          </form>
        </Card>

        <Card>
          <CardHeader title="改状态" />
          <form aria-label="改状态" className="space-y-4" onSubmit={event => handleSubmit(event, 'board_status')}>
            <Select label="任务号" id="command-task" name="task_id" required defaultValue=""
              disabled={tasksLoading || tasks.length === 0}
              options={[{ value: '', label: tasksLoading ? '正在加载任务…' : tasks.length ? '请选择任务' : '暂无可选任务' },
                ...tasks.map(task => ({ value: task.id, label: `${task.id} · ${task.title}` }))]} />
            <Select label="新状态" id="command-status" name="status" options={statuses} />
            {taskError && <div role="alert"><AlertBanner type="error" message={taskError} onRetry={loadTasks} /></div>}
            {!tasksLoading && !taskError && tasks.length === 0 && <p className="text-sm text-slate-400">任务列表为空，暂时无法提交改状态指令。</p>}
            <Button type="submit" variant="primary" disabled={submitting || !token || tasksLoading || tasks.length === 0}>提交改状态指令</Button>
          </form>
        </Card>

        <CommandMessageForms fields={messageFields} onFieldsChange={setMessageFields} onSubmit={handleSubmit} disabled={submitting || !token} staticMode={api.staticMode} />
      </div>

      <Card>
        <CardHeader title="指令列表" action={<Button onClick={loadCommands} loading={listLoading} disabled={!token}>刷新指令列表</Button>} />
        {listLoading && <p role="status" className="text-sm text-slate-400">正在读取指令…</p>}
        {listError && <div role="alert"><AlertBanner type="error" message={listError} onRetry={loadCommands} /></div>}
        {commands && <div className="space-y-6">
          <section aria-label="pending 指令">
            <h3 className="text-sm font-semibold mb-2">待处理（pending） · {commands.pending.length}</h3>
            <CommandTable entries={commands.pending} pending staticMode={api.staticMode} confirmingId={confirmingId}
              disabled={submitting || !token} onCancel={handleCancel} />
          </section>
          <section aria-label="done 指令">
            <h3 className="text-sm font-semibold mb-2">已处理（done） · {commands.done.length}</h3>
            <CommandTable entries={commands.done} pending={false} staticMode={api.staticMode} confirmingId={null}
              disabled={submitting || !token} onCancel={handleCancel} />
          </section>
        </div>}
      </Card>
    </div>
  );
}
