import React from 'react';
import { Clock, ShieldAlert, CheckCircle2 } from 'lucide-react';
import type { SourceSnapshot } from '../types';
import { FreshnessBadge } from '../design-system';

interface FreshnessIndicatorProps {
  sourceSnapshot?: SourceSnapshot;
  className?: string;
  compact?: boolean;
}

export const FreshnessIndicator: React.FC<FreshnessIndicatorProps> = ({
  sourceSnapshot,
  className = '',
  compact = false,
}) => {
  if (!sourceSnapshot) {
    return (
      <div className={`text-xs text-slate-500 font-mono ${className}`}>
        [Source Meta: N/A]
      </div>
    );
  }

  const { sources, generated_at, partial } = sourceSnapshot;

  if (compact) {
    return (
      <div className={`flex items-center gap-2 text-xs ${className}`}>
        {partial ? (
          <span className="flex items-center gap-1 text-amber-400 font-mono text-[11px] px-1.5 py-0.5 rounded bg-amber-950/60 border border-amber-800">
            <ShieldAlert className="h-3 w-3" />
            PARTIAL
          </span>
        ) : (
          <span className="flex items-center gap-1 text-emerald-400 font-mono text-[11px] px-1.5 py-0.5 rounded bg-emerald-950/60 border border-emerald-800">
            <CheckCircle2 className="h-3 w-3" />
            FULL
          </span>
        )}
        <span className="text-slate-400 font-mono text-[11px]">
          {new Date(generated_at).toLocaleTimeString()}
        </span>
      </div>
    );
  }

  return (
    <div
      className={`rounded-xl border border-slate-800 bg-slate-900/50 p-4 text-xs space-y-3 ${className}`}
    >
      <div className="flex flex-wrap sm:flex-nowrap items-center justify-between gap-2 border-b border-slate-800/80 pb-2.5">
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-indigo-400" />
          <span className="font-semibold text-slate-200">数据源时效与新鲜度快照 (NB-N04)</span>
        </div>
        <div className="flex flex-wrap items-center gap-2 font-mono">
          {partial ? (
            <span className="px-2 py-0.5 rounded bg-amber-950/80 border border-amber-800 text-amber-300 font-bold text-[11px]">
              ⚠️ partial=true (存在降级源)
            </span>
          ) : (
            <span className="px-2 py-0.5 rounded bg-emerald-950/80 border border-emerald-800 text-emerald-300 font-bold text-[11px]">
              ✓ partial=false (全部新鲜)
            </span>
          )}
          <span className="text-slate-400 text-[11px]">
            生成于: {new Date(generated_at).toLocaleTimeString()}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {sources.map((src, i) => (
          <div
            key={i}
            className="p-2.5 rounded-lg border border-slate-800/80 bg-slate-950/50 space-y-1.5"
          >
            <div className="flex items-center justify-between">
              <span className="font-mono font-bold text-slate-300 uppercase">{src.source}</span>
              <FreshnessBadge freshness={src.freshness} stale={src.stale} size="sm" />
            </div>
            <div className="text-[11px] font-mono text-slate-400 truncate" title={src.source_ref || ''}>
              Ref: {src.source_ref || 'none'}
            </div>
            <div className="text-[10px] text-slate-500 flex justify-between">
              <span>实测: {src.observed_at ? new Date(src.observed_at).toLocaleTimeString() : 'null'}</span>
              <span>采集: {src.fetched_at ? new Date(src.fetched_at).toLocaleTimeString() : 'null'}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
