import React from 'react';
import { Terminal, ChevronRight } from 'lucide-react';
import type { EventList, Event } from '../types';
import {
  Card,
  Select,
  Button,
  SeverityBadge,
  EventStateBadge,
  TableSkeleton,
  EmptyState,
  AlertBanner,
} from '../design-system';
import { FreshnessIndicator } from '../components/FreshnessIndicator';

interface EventsViewProps {
  eventList: EventList | null;
  loading: boolean;
  error: Error | null;
  nodeFilter: string;
  setNodeFilter: (n: string) => void;
  stateFilter: string;
  setStateFilter: (s: string) => void;
  onSelectEvent: (evt: Event) => void;
  onResetFilters: () => void;
  onRetry: () => void;
}

export const EventsView: React.FC<EventsViewProps> = ({
  eventList,
  loading,
  error,
  nodeFilter,
  setNodeFilter,
  stateFilter,
  setStateFilter,
  onSelectEvent,
  onResetFilters,
  onRetry,
}) => {
  const nodeOptions = [
    { value: '', label: '全部节点 (All Nodes)' },
    { value: 'node-1', label: 'node-1' },
    { value: 'node-2', label: 'node-2' },
    { value: 'node-3', label: 'node-3' },
  ];

  const stateOptions = [
    { value: '', label: '全部状态 (All States)' },
    { value: 'ACKED', label: 'ACKED (已确认)' },
    { value: 'NEEDS_ATTENTION', label: 'NEEDS_ATTENTION (待关注)' },
    { value: 'NEEDS_RECONCILIATION', label: 'NEEDS_RECONCILIATION (待对账)' },
    { value: 'REJECTED', label: 'REJECTED (已驳回)' },
    { value: 'SUPERSEDED', label: 'SUPERSEDED (已替代)' },
    { value: 'CLOSED_INTERNAL', label: 'CLOSED_INTERNAL (已闭环)' },
  ];

  const isFiltered = Boolean(nodeFilter || stateFilter);

  const filteredEvents =
    eventList?.items.filter((evt) => {
      if (nodeFilter && evt.node_id !== nodeFilter) return false;
      if (stateFilter && evt.state !== stateFilter) return false;
      return true;
    }) || [];

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-100 flex items-center gap-2">
            <Terminal className="h-6 w-6 text-indigo-400" />
            事件流水审计 (Events Audit Stream)
          </h2>
          <p className="text-xs text-slate-400 mt-1">
            按检测时间降序分页 · 字段级脱敏保护 · 严禁将脱敏自由文本当 HTML 渲染
          </p>
        </div>

        {eventList && <FreshnessIndicator sourceSnapshot={eventList.source_meta} compact />}
      </div>

      {/* Filter Bar */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row items-center gap-3">
          <div className="w-full sm:w-56">
            <Select
              options={nodeOptions}
              value={nodeFilter}
              onChange={(e) => setNodeFilter(e.target.value)}
            />
          </div>

          <div className="w-full sm:w-64">
            <Select
              options={stateOptions}
              value={stateFilter}
              onChange={(e) => setStateFilter(e.target.value)}
            />
          </div>

          {isFiltered && (
            <Button size="sm" variant="outline" onClick={onResetFilters}>
              清空筛选
            </Button>
          )}
        </div>
      </Card>

      {/* Error Banner */}
      {error && (
        <AlertBanner
          type="error"
          title="查询事件流水失败"
          message={error.message}
          onRetry={onRetry}
        />
      )}

      {/* Loading Skeletons */}
      {loading && !eventList && <TableSkeleton rows={5} />}

      {/* Events Table */}
      {eventList && (
        <>
          <div className="flex items-center justify-between text-xs text-slate-400 px-1">
            <span>
              显示 <strong className="text-slate-200 font-mono">{filteredEvents.length}</strong> /{' '}
              {eventList.total} 条事件
            </span>
            <span className="font-mono text-[11px]">按 detected_at 降序</span>
          </div>

          {filteredEvents.length === 0 ? (
            <EmptyState
              title="未找到匹配事件"
              description="当前过滤条件下没有事件流水记录。"
              actionText="清空筛选"
              onAction={onResetFilters}
            />
          ) : (
            <div className="rounded-xl border border-slate-800/90 bg-slate-900/60 overflow-x-auto shadow-md">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-slate-800 bg-slate-950/60 font-mono text-slate-400 uppercase text-[11px]">
                    <th className="py-3 px-4">事件编号</th>
                    <th className="py-3 px-3">严重级别</th>
                    <th className="py-3 px-3">状态 (EventState)</th>
                    <th className="py-3 px-3">关联任务</th>
                    <th className="py-3 px-3">责任节点</th>
                    <th className="py-3 px-4">事件摘要</th>
                    <th className="py-3 px-3">重试与唤醒</th>
                    <th className="py-3 px-3">检测时间</th>
                    <th className="py-3 px-4 text-right">操作</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/60 font-sans">
                  {filteredEvents.map((evt) => (
                    <tr
                      key={evt.id}
                      onClick={() => onSelectEvent(evt)}
                      className="hover:bg-slate-800/40 cursor-pointer transition-colors group"
                    >
                      <td className="py-3.5 px-4 font-mono font-bold text-slate-200 whitespace-nowrap">
                        {evt.id}
                      </td>
                      <td className="py-3.5 px-3 whitespace-nowrap">
                        <SeverityBadge severity={evt.severity} />
                      </td>
                      <td className="py-3.5 px-3 whitespace-nowrap">
                        <EventStateBadge state={evt.state} size="sm" />
                      </td>
                      <td className="py-3.5 px-3 font-mono text-indigo-400 whitespace-nowrap">
                        {evt.task_id || '-'}
                      </td>
                      <td className="py-3.5 px-3 font-mono text-slate-300 whitespace-nowrap">
                        {evt.node_id || '-'}
                      </td>
                      <td className="py-3.5 px-4 text-slate-300 max-w-[320px] truncate group-hover:text-white">
                        {evt.summary || '无摘要'}
                      </td>
                      <td className="py-3.5 px-3 font-mono text-slate-400 whitespace-nowrap text-[11px]">
                        重试: {evt.retry.attempt_count ?? 0}
                      </td>
                      <td className="py-3.5 px-3 font-mono text-slate-400 whitespace-nowrap text-[11px]">
                        {evt.timestamps.detected_at
                          ? new Date(evt.timestamps.detected_at).toLocaleTimeString()
                          : '-'}
                      </td>
                      <td className="py-3.5 px-4 text-right whitespace-nowrap">
                        <Button size="sm" variant="ghost" className="p-1">
                          <ChevronRight className="h-4 w-4 text-slate-400 group-hover:text-indigo-400" />
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  );
};
