import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Activity,
  Server,
  Layers,
  Radio,
  FileEdit,
  Terminal,
  Lock,
  Send,
} from 'lucide-react';
import { api, apiClient } from './api';
import type { Overview, NodeList, TaskList, EventList, Runtime } from './types';
import { Navbar, type NavTab } from './components/Navbar';
import { AccessKeyModal } from './components/AccessKeyModal';
import { DetailDrawer, type DrawerTarget } from './components/DetailDrawer';
import { OverviewView } from './views/OverviewView';
import { NodesView } from './views/NodesView';
import { emptyTaskFilters, TasksView } from './views/TasksView';
import { RuntimeView } from './views/RuntimeView';
import { NotesTodosView } from './views/NotesTodosView';
import { EventsView } from './views/EventsView';
import { CommandsView } from './views/CommandsView';
import { AlertBanner, Button } from './design-system';
import { DataTime } from './components/DataTime';
import { startAutoRefresh } from './api/auto-refresh';
import { loadExportStatus, type ExportStatus } from './api/export-status';

export const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<NavTab>('overview');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Core datasets
  const [overview, setOverview] = useState<Overview | null>(null);
  const [nodeList, setNodeList] = useState<NodeList | null>(null);
  const [taskList, setTaskList] = useState<TaskList | null>(null);
  const [eventList, setEventList] = useState<EventList | null>(null);
  const [runtime, setRuntime] = useState<Runtime | null>(null);
  const [exportStatus, setExportStatus] = useState<ExportStatus | null>(null);

  // Loading & Error states
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [globalError, setGlobalError] = useState<Error | null>(null);

  // Tower Access Key Modal state
  const [showKeyModal, setShowKeyModal] = useState(false);
  const [hasKey, setHasKey] = useState(Boolean(apiClient.getAccessKey()));

  // Task center search/filters
  const [taskFilters, setTaskFilters] = useState(emptyTaskFilters);

  // Events filters
  const [nodeFilter, setNodeFilter] = useState('');
  const [eventStateFilter, setEventStateFilter] = useState('');

  // Active detail drawer state
  const [drawerTarget, setDrawerTarget] = useState<DrawerTarget>(null);

  // Load Overview & Runtime
  const loadOverviewAndRuntime = useCallback(async () => {
    try {
      const [ov, rt] = await Promise.all([api.getOverview(), api.getRuntime()]);
      setOverview(ov);
      setRuntime(rt);
    } catch (err: unknown) {
      setGlobalError(err instanceof Error ? err : new Error(String(err)));
    }
  }, []);

  // Load Nodes
  const loadNodes = useCallback(async () => {
    try {
      const res = await api.listNodes();
      setNodeList(res);
    } catch (err: unknown) {
      setGlobalError(err instanceof Error ? err : new Error(String(err)));
    }
  }, []);

  // Load the available task snapshot for client-side filtering.
  const loadTasks = useCallback(async () => {
    try {
      const res = await api.listTasks({ limit: 100 });
      setTaskList(res);
    } catch (err: unknown) {
      setGlobalError(err instanceof Error ? err : new Error(String(err)));
    }
  }, []);

  // Load Events
  const loadEvents = useCallback(async () => {
    try {
      const res = await api.listEvents({
        node_id: (nodeFilter as any) || undefined,
      });
      setEventList(res);
    } catch (err: unknown) {
      setGlobalError(err instanceof Error ? err : new Error(String(err)));
    }
  }, [nodeFilter]);

  // Primary loader based on current active tab
  const refreshActiveData = useCallback(async () => {
    setLoading(true);
    setGlobalError(null);
    setHasKey(Boolean(apiClient.getAccessKey()));
    try {
      await Promise.all([loadOverviewAndRuntime(), loadNodes(), loadTasks(), loadEvents()]);
    } catch (err: unknown) {
      setGlobalError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setLoading(false);
    }
  }, [loadOverviewAndRuntime, loadNodes, loadTasks, loadEvents]);

  // Trigger POST /api/v1/refresh
  const handleGlobalRefresh = async () => {
    setRefreshing(true);
    try {
      await api.refreshReadModels();
      await refreshActiveData();
    } catch (err: unknown) {
      setGlobalError(err instanceof Error ? err : new Error('刷新失败'));
    } finally {
      setRefreshing(false);
    }
  };

  const autoRefresh = useRef(handleGlobalRefresh);
  autoRefresh.current = handleGlobalRefresh;
  useEffect(() => {
    if (api.staticMode || !hasKey) return;
    return startAutoRefresh(() => autoRefresh.current());
  }, [hasKey]);

  useEffect(() => {
    if (!api.staticMode) return;
    let active = true;
    const load = async () => {
      const status = await loadExportStatus();
      if (active) setExportStatus(status);
    };
    void load();
    const timer = setInterval(load, 60_000);
    return () => { active = false; clearInterval(timer); };
  }, []);

  // Initial mount
  useEffect(() => {
    refreshActiveData();
  }, [refreshActiveData]);

  const handleSelectTaskId = async (taskId: string) => {
    try {
      const task = await api.getTask(taskId);
      setDrawerTarget({ type: 'task', data: task });
    } catch (err: unknown) {
      alert(err instanceof Error ? err.message : '无法获取任务详情');
    }
  };

  const isAuthError = Boolean(
    !api.staticMode && globalError &&
      ((globalError as any).code === 'AUTH_REQUIRED' ||
        globalError.message.includes('access key') ||
        globalError.message.includes('401'))
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans selection:bg-indigo-500/30 selection:text-indigo-200">
      {/* Top Header Navigation and snapshot health */}
      <div className="sticky top-0 z-30">
      <Navbar
        activeTab={activeTab}
        onTabChange={(tab) => {
          setActiveTab(tab);
          setMobileMenuOpen(false);
        }}
        onRefresh={handleGlobalRefresh}
        isRefreshing={refreshing}
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
        onOpenKeyModal={() => setShowKeyModal(true)}
        hasAccessKey={hasKey}
        readOnly={api.staticMode}
      />
      <DataTime at={api.staticMode ? apiClient.snapshotRefreshedAt : runtime?.refresh_meta.last_refreshed_at ?? null}
        error={Boolean(globalError || runtime?.refresh_meta.last_error)} staticMode={api.staticMode}
        failure={api.staticMode ? (exportStatus?.last_failure_at ? { at: exportStatus.last_failure_at, reason: exportStatus.last_failure_reason || '未知原因' } : null) : runtime?.last_export_failure}
        successAt={api.staticMode ? exportStatus?.last_success_at : runtime?.last_export_success_at} />
      </div>

      {/* Mobile Nav Drawer */}
      {mobileMenuOpen && (
        <div className="lg:hidden border-b border-slate-800 bg-slate-900/95 p-4 space-y-2 animate-in slide-in-from-top">
          <button
            onClick={() => {
              setActiveTab('overview');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'overview' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <Activity className="h-4 w-4" /> 全景总览
          </button>
          <button
            onClick={() => {
              setActiveTab('nodes');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'nodes' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <Server className="h-4 w-4" /> 节点管理 (3)
          </button>
          <button
            onClick={() => {
              setActiveTab('tasks');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'tasks' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <Layers className="h-4 w-4" /> 任务中心 (7D)
          </button>
          <button
            onClick={() => {
              setActiveTab('runtime');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'runtime' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <Radio className="h-4 w-4" /> 运行时监控 (双巡逻)
          </button>
          <button
            onClick={() => {
              setActiveTab('notes-todos');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'notes-todos'
                ? 'bg-indigo-600 text-white'
                : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <FileEdit className="h-4 w-4" /> 备忘与待办 (SQLite)
          </button>
          <button
            onClick={() => {
              setActiveTab('events');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'events' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <Terminal className="h-4 w-4" /> 事件流水
          </button>
          <button
            onClick={() => {
              setActiveTab('commands');
              setMobileMenuOpen(false);
            }}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium ${
              activeTab === 'commands' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'
            }`}
          >
            <Send className="h-4 w-4" /> 指令
          </button>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8">
        {api.staticMode && (
          <div role="status" className="mb-4 rounded-lg border border-indigo-500/30 bg-indigo-950/40 p-3 text-sm text-indigo-200">
            静态快照 · 只读 · 快照时间：{apiClient.snapshotRefreshedAt ?? '加载中'}
            <span className="block text-xs mt-1">快照只读，全量同步不可用；指令页连接本地控制层后可发送指令。更新快照后重新打开页面。</span>
          </div>
        )}
        {globalError && (
          <div className="mb-6 space-y-3">
            <AlertBanner
              type="error"
              title={isAuthError ? '需要 Tower 访问密钥 (AUTH_REQUIRED)' : '全局数据请求异常'}
              message={
                isAuthError
                  ? '后端 API 要求通过 X-CT-Access-Key 请求头进行独立单租户鉴权。请配置部署时设定的高熵访问密钥。'
                  : globalError.message
              }
              onRetry={refreshActiveData}
            />
            {isAuthError && (
              <div className="flex justify-end">
                <Button size="sm" variant="primary" onClick={() => setShowKeyModal(true)}>
                  配置访问密钥
                </Button>
              </div>
            )}
          </div>
        )}

        {/* Tab Switcher */}
        {activeTab === 'overview' && (
          <OverviewView
            overview={overview}
            staticMode={api.staticMode}
            snapshotTime={apiClient.snapshotRefreshedAt}
            pendingDecisions={apiClient.snapshotPendingDecisions}
            loading={loading}
            error={globalError}
            onNavigateTab={(tab) => setActiveTab(tab)}
            onSelectTask={(task) => setDrawerTarget({ type: 'task', data: task })}
            onSelectNode={(node) => setDrawerTarget({ type: 'node', data: node })}
            onSelectEvent={(evt) => setDrawerTarget({ type: 'event', data: evt })}
            onRetry={refreshActiveData}
          />
        )}

        {activeTab === 'nodes' && (
          <NodesView
            nodeList={nodeList}
            loading={loading}
            error={globalError}
            onSelectNode={(node) => setDrawerTarget({ type: 'node', data: node })}
            onSelectTaskId={handleSelectTaskId}
            onRetry={loadNodes}
          />
        )}

        {activeTab === 'tasks' && (
          <TasksView
            taskList={taskList}
            loading={loading}
            error={globalError}
            searchQuery={taskFilters.searchQuery}
            setSearchQuery={(searchQuery) => setTaskFilters(filters => ({ ...filters, searchQuery }))}
            statusFilter={taskFilters.statusFilter}
            setStatusFilter={(statusFilter) => setTaskFilters(filters => ({ ...filters, statusFilter }))}
            assigneeFilter={taskFilters.assigneeFilter}
            setAssigneeFilter={(assigneeFilter) => setTaskFilters(filters => ({ ...filters, assigneeFilter }))}
            onSelectTask={(task) => setDrawerTarget({ type: 'task', data: task })}
            onResetFilters={() => setTaskFilters(emptyTaskFilters)}
            onRetry={loadTasks}
          />
        )}

        {activeTab === 'runtime' && (
          <RuntimeView
            runtime={runtime}
            loading={loading}
            error={globalError}
            onRefreshRuntime={loadOverviewAndRuntime}
            onRetry={loadOverviewAndRuntime}
          />
        )}

        {activeTab === 'notes-todos' && <NotesTodosView />}

        {activeTab === 'commands' && <CommandsView />}

        {activeTab === 'events' && (
          <EventsView
            eventList={eventList}
            loading={loading}
            error={globalError}
            nodeFilter={nodeFilter}
            setNodeFilter={setNodeFilter}
            stateFilter={eventStateFilter}
            setStateFilter={setEventStateFilter}
            onSelectEvent={(evt) => setDrawerTarget({ type: 'event', data: evt })}
            onResetFilters={() => {
              setNodeFilter('');
              setEventStateFilter('');
            }}
            onRetry={loadEvents}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-slate-900 bg-slate-950 px-4 py-6 text-xs text-slate-500 text-center">
        <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Lock className="h-3.5 w-3.5 text-indigo-400" />
            <span>{api.staticMode ? 'Muse Control Tower · 静态快照 · 只读' : 'Muse Control Tower Stage 3 · Real API Integration · Contract 1.1.0 (commit db649ab)'}</span>
          </div>
          <div className="flex items-center gap-4 font-mono text-[11px]">
            <span>{api.staticMode ? 'snapshot.json' : 'FastAPI Backend (Real Data)'}</span>
            <span>·</span>
            <span>{api.staticMode ? 'React Frontend (Static Snapshot)' : 'React Frontend (Live Client)'}</span>
            <span>·</span>
            <span>Architecture (ChatGPT)</span>
          </div>
        </div>
      </footer>

      {/* Reusable Detail Drawer */}
      <DetailDrawer target={drawerTarget} onClose={() => setDrawerTarget(null)} />

      {/* Access Key Configuration Modal */}
      {!api.staticMode && <AccessKeyModal
        isOpen={showKeyModal}
        onClose={() => setShowKeyModal(false)}
        onSaved={() => {
          setHasKey(Boolean(apiClient.getAccessKey()));
          refreshActiveData();
        }}
      />}
    </div>
  );
};
