import React, { useState } from 'react';
import {
  Search,
  Layers,
  LayoutGrid,
  List,
  AlertTriangle,
  RotateCcw,
  ChevronRight,
} from 'lucide-react';
import type { TaskList, Task } from '../types';
import {
  Card,
  CardHeader,
  Input,
  Select,
  Button,
  DerivedStatusBadge,
  BoardStatusBadge,
  EventStateBadge,
  TableSkeleton,
  EmptyState,
  AlertBanner,
} from '../design-system';
import { FreshnessIndicator } from '../components/FreshnessIndicator';
import { TaskTelemetry } from '../components/TaskTelemetry';

interface TasksViewProps {
  taskList: TaskList | null;
  loading: boolean;
  error: Error | null;
  searchQuery: string;
  setSearchQuery: (q: string) => void;
  statusFilter: string;
  setStatusFilter: (s: string) => void;
  assigneeFilter: string;
  setAssigneeFilter: (a: string) => void;
  onSelectTask: (task: Task) => void;
  onResetFilters: () => void;
  onRetry: () => void;
}

export const emptyTaskFilters = { searchQuery: '', statusFilter: '', assigneeFilter: '' };

export function filterTasks(tasks: Task[], searchQuery: string, statusFilter: string, assigneeFilter: string): Task[] {
  const query = searchQuery.toLowerCase();
  return tasks.filter(task =>
    (!statusFilter || (task.board_status ?? 'unlisted') === statusFilter) &&
    (!assigneeFilter || task.assignee === assigneeFilter) &&
    (!query || task.id.toLowerCase().includes(query) || task.title.toLowerCase().includes(query))
  );
}

function localDateKey(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

export function formatTrendDuration(seconds: number | null): string {
  if (seconds === null) return '—';
  const minutes = Math.round(seconds / 60);
  return minutes >= 60 ? `${Math.floor(minutes / 60)}小时${minutes % 60}分` : `${minutes}分钟`;
}

export function taskTrend(tasks: Task[], now = new Date()) {
  const days = Array.from({ length: 7 }, (_, index) => {
    const date = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 6 + index);
    return { date: localDateKey(date), count: 0, totalSeconds: 0, durationCount: 0 };
  });
  const byDate = new Map(days.map(day => [day.date, day]));
  for (const task of tasks) {
    if (task.board_status !== '完成' || !task.telemetry?.accepted_at) continue;
    const accepted = new Date(task.telemetry.accepted_at);
    if (Number.isNaN(accepted.getTime())) continue;
    const day = byDate.get(localDateKey(accepted));
    if (!day) continue;
    day.count++;
    const seconds = task.telemetry.total_seconds;
    if (seconds != null) {
      day.totalSeconds += seconds;
      day.durationCount++;
    }
  }
  return days.map(day => ({
    date: day.date,
    count: day.count,
    average: day.durationCount ? day.totalSeconds / day.durationCount : null,
  }));
}

export const TasksView: React.FC<TasksViewProps> = ({
  taskList,
  loading,
  error,
  searchQuery,
  setSearchQuery,
  statusFilter,
  setStatusFilter,
  assigneeFilter,
  setAssigneeFilter,
  onSelectTask,
  onResetFilters,
  onRetry,
}) => {
  const [viewMode, setViewMode] = useState<'table' | 'cards'>('table');

  const tasks = taskList?.items ?? [];
  const statusOptions = [
    { value: '', label: '全部状态' },
    ...Array.from(new Set(tasks.map(task => task.board_status ?? 'unlisted')))
      .map(value => ({ value, label: value })),
  ];
  const assigneeOptions = [
    { value: '', label: '全部负责人' },
    ...Array.from(new Set(tasks.flatMap(task => task.assignee ? [task.assignee] : [])))
      .map(value => ({ value, label: value })),
  ];
  const filteredTasks = filterTasks(tasks, searchQuery, statusFilter, assigneeFilter);
  const trend = taskTrend(tasks);

  const isFiltered = Boolean(searchQuery || statusFilter || assigneeFilter);

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-100 flex items-center gap-2">
            <Layers className="h-6 w-6 text-indigo-400" />
            任务全景中心 (Task Center)
          </h2>
          <p className="text-xs text-slate-400 mt-1">
            任务状态以 BOARD 为准 · BOARD 外任务标 unlisted 并单列
          </p>
        </div>

        {taskList && <FreshnessIndicator sourceSnapshot={taskList.source_meta} compact />}
      </div>

      {/* Filter / Search Bar */}
      <Card className="p-4">
        <div className="flex flex-col md:flex-row items-stretch md:items-center gap-3">
          <div className="flex-1">
            <Input
              aria-label="搜索任务编号或标题"
              placeholder="搜索任务编号或标题 (如 T-DEMO, 验收, 巡逻)..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              icon={<Search className="h-4 w-4" />}
            />
          </div>

          <div className="w-full md:w-56">
            <Select
              aria-label="状态"
              options={statusOptions}
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
            />
          </div>

          <div className="w-full md:w-44">
            <Select
              aria-label="负责人"
              options={assigneeOptions}
              value={assigneeFilter}
              onChange={(e) => setAssigneeFilter(e.target.value)}
            />
          </div>

          <div className="flex flex-wrap items-center gap-2 shrink-0">
            {isFiltered && (
              <Button
                variant="outline"
                size="md"
                onClick={onResetFilters}
                icon={<RotateCcw className="h-3.5 w-3.5" />}
                title="清除筛选"
              >
                清除筛选
              </Button>
            )}

            <div className="flex items-center border border-slate-800 rounded-lg p-0.5 bg-slate-950">
              <button
                onClick={() => setViewMode('table')}
                className={`p-1.5 rounded cursor-pointer transition-colors ${
                  viewMode === 'table' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
                }`}
                title="表格视图"
              >
                <List className="h-4 w-4" />
              </button>
              <button
                onClick={() => setViewMode('cards')}
                className={`p-1.5 rounded cursor-pointer transition-colors ${
                  viewMode === 'cards' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
                }`}
                title="卡片网格"
              >
                <LayoutGrid className="h-4 w-4" />
              </button>
            </div>
          </div>
        </div>
      </Card>

      {/* Error Banner */}
      {error && (
        <AlertBanner
          type="error"
          title="查询任务列表失败"
          message={error.message}
          onRetry={onRetry}
        />
      )}

      {/* Loading Skeletons */}
      {loading && !taskList && <TableSkeleton rows={6} />}

      {/* Data display */}
      {taskList && (
        <>
          <Card>
            <CardHeader title="近 7 天（全量）" />
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-300">
                <thead className="text-slate-400"><tr><th className="py-2">日期</th><th>完成任务数</th><th>平均耗时</th></tr></thead>
                <tbody>
                  {trend.map(day => <tr key={day.date} className="border-t border-slate-800/60">
                    <td className="py-2 font-mono">{day.date}</td>
                    <td>{day.count}</td>
                    <td>{formatTrendDuration(day.average)}</td>
                  </tr>)}
                </tbody>
              </table>
            </div>
            <p className="mt-2 text-xs text-slate-400">按 accepted_at 计，平均耗时只计有时长的任务</p>
          </Card>
          <div className="flex items-center justify-between text-xs text-slate-400 px-1">
            <span>
              显示 {filteredTasks.length} / {tasks.length} 条
            </span>
            <span className="font-mono text-[11px]">按 Task ID 升序排序</span>
          </div>

          {filteredTasks.length === 0 ? (
            <EmptyState
              title="没有匹配的任务"
              description="请尝试调整搜索关键词或清空状态/负责人过滤条件。"
              actionText="重置所有筛选"
              onAction={onResetFilters}
            />
          ) : !filteredTasks.some(task => task.derived_status !== 'unlisted') ? null : viewMode === 'table' ? (
            /* Table View */
            <div className="rounded-xl border border-slate-800/90 bg-slate-900/60 overflow-x-auto shadow-md">
              <table className="block sm:table w-full text-left text-xs">
                <thead className="hidden sm:table-header-group">
                  <tr className="border-b border-slate-800 bg-slate-950/60 font-mono text-slate-400 uppercase text-[11px]">
                    <th className="py-3 px-4">任务编号</th>
                    <th className="py-3 px-4">标题</th>
                    <th className="py-3 px-3">负责人</th>
                    <th className="py-3 px-3">BOARD 六态</th>
                    <th className="py-3 px-3">交付状态</th>
                    <th className="py-3 px-3">验收状态</th>
                    <th className="py-3 px-3">事件状态</th>
                    <th className="py-3 px-3">任务状态（BOARD）</th>
                    <th className="py-3 px-3">收据与冲突</th>
                    <th className="py-3 px-4 text-right">操作</th>
                  </tr>
                </thead>
                <tbody className="block sm:table-row-group divide-y divide-slate-800/60 font-sans">
                  {filteredTasks.filter(task => task.derived_status !== 'unlisted').map((task) => (
                    <tr
                      key={task.id}
                      onClick={() => onSelectTask(task)}
                      className="block sm:table-row py-2 sm:py-0 hover:bg-slate-800/40 cursor-pointer transition-colors group"
                    >
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 font-mono font-bold text-indigo-400 break-all sm:whitespace-nowrap">
                        {task.id}
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:max-w-[280px] break-words">
                        <div className="font-medium text-slate-100 sm:truncate group-hover:text-indigo-300 transition-colors">
                          {task.title}
                        </div>
                        {task.issue_number && (
                          <div className="text-[11px] font-mono text-slate-500 mt-0.5">
                            Issue #{task.issue_number}
                          </div>
                        )}
                        <TaskTelemetry task={task} />
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 font-mono break-words sm:whitespace-nowrap before:content-['负责人:_'] sm:before:content-none before:text-slate-400">
                        {task.assignee ? (
                          <span className="text-slate-300 font-semibold">{task.assignee}</span>
                        ) : (
                          <span className="text-slate-600">未指派</span>
                        )}
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 sm:whitespace-nowrap">
                        <span className="sm:hidden text-slate-400 mr-2">BOARD 六态:</span><BoardStatusBadge status={task.board_status} />
                        {task.wait && <span className="ml-2 text-slate-300"><span className="inline-block px-2 py-0.5 text-xs rounded border bg-blue-950/80 text-blue-300 border-blue-800">等待中</span> {task.wait.reason}{task.wait.until && ` · ${task.wait.until}`}</span>}
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 sm:whitespace-nowrap font-mono text-[11px]">
                        <span className="sm:hidden text-slate-400 mr-2">交付状态:</span><span
                          className={`px-1.5 py-0.5 rounded ${
                            task.delivery_status === 'delivered'
                              ? 'bg-emerald-950/60 text-emerald-400 border border-emerald-800'
                              : 'bg-slate-900 text-slate-500'
                          }`}
                        >
                          {task.delivery_status}
                        </span>
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 sm:whitespace-nowrap font-mono text-[11px]">
                        <span className="sm:hidden text-slate-400 mr-2">验收状态:</span><span
                          className={`px-1.5 py-0.5 rounded ${
                            task.acceptance_status === 'accepted'
                              ? 'bg-emerald-950/60 text-emerald-400 border border-emerald-800'
                              : task.acceptance_status === 'rejected'
                              ? 'bg-rose-950/60 text-rose-400 border border-rose-800'
                              : task.acceptance_status === 'unverified'
                              ? 'bg-yellow-950/60 text-yellow-400 border border-yellow-800'
                              : 'bg-slate-900 text-slate-500'
                          }`}
                        >
                          {task.acceptance_status}
                        </span>
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 sm:whitespace-nowrap">
                        <span className="sm:hidden text-slate-400 mr-2">事件状态:</span><EventStateBadge state={task.event_status} size="sm" />
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 sm:whitespace-nowrap">
                        <span className="sm:hidden text-slate-400 mr-2">任务状态:</span><DerivedStatusBadge status={task.derived_status} size="sm" />
                      </td>
                      <td className="block sm:table-cell py-1 sm:py-3.5 px-4 sm:px-3 sm:whitespace-nowrap">
                        <div className="flex items-center gap-1.5 text-[11px] font-mono">
                          {task.receipts.length > 0 ? (
                            <span
                              className="px-1.5 py-0.5 rounded bg-indigo-950/70 border border-indigo-800 text-indigo-300"
                              title={`${task.receipts.length} 份独立收据`}
                            >
                              {task.receipts.length} 收据
                            </span>
                          ) : (
                            <span className="text-slate-600">0 收据</span>
                          )}

                          {task.source_conflicts.length > 0 && (
                            <span
                              className="px-1.5 py-0.5 rounded bg-amber-950/70 border border-amber-800 text-amber-300 flex items-center gap-1"
                              title={task.source_conflicts[0].reason}
                            >
                              <AlertTriangle className="h-3 w-3" />
                              冲突
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="hidden sm:table-cell py-3.5 px-4 text-right whitespace-nowrap">
                        <Button size="sm" variant="ghost" className="p-1">
                          <ChevronRight className="h-4 w-4 text-slate-400 group-hover:text-indigo-400" />
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            /* Cards View */
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredTasks.filter(task => task.derived_status !== 'unlisted').map((task) => (
                <Card
                  key={task.id}
                  onClick={() => onSelectTask(task)}
                  className="cursor-pointer hover:border-indigo-500/50 transition-all space-y-3"
                >
                  <div className="flex items-start justify-between gap-2">
                    <span className="font-mono font-bold text-sm text-indigo-400">{task.id}</span>
                    <DerivedStatusBadge status={task.derived_status} size="sm" />
                  </div>

                  <h4 className="text-sm font-semibold text-slate-100 line-clamp-2">{task.title}</h4>

                  <div className="grid grid-cols-2 gap-2 text-xs pt-2 border-t border-slate-800/80 text-slate-400">
                    <div>
                      <span>负责人: </span>
                      <strong className="text-slate-200 font-mono">{task.assignee || '无'}</strong>
                    </div>
                    <div>
                      <span>BOARD: </span>
                      <strong className="text-slate-200">{task.board_status || '无'}</strong>
                    </div>
                  </div>

                  <div className="pt-2 border-t border-slate-800/60 flex items-center justify-between text-[11px] text-slate-500 font-mono">
                    <span>收据: {task.receipts.length}</span>
                    {task.source_conflicts.length > 0 && (
                      <span className="text-amber-400 flex items-center gap-1">
                        <AlertTriangle className="h-3 w-3" /> 有证据冲突
                      </span>
                    )}
                  </div>
                  <TaskTelemetry task={task} />
                </Card>
              ))}
            </div>
          )}
        </>
      )}
      {taskList && filteredTasks.some(task => task.derived_status === 'unlisted') && <Card>
        <CardHeader title="BOARD 外任务 · unlisted" description="未登记任务，不计入 BOARD 统计。" />
        {filteredTasks.filter(task => task.derived_status === 'unlisted').map(task => (
          <div key={task.id} className="py-2">
            <button onClick={() => onSelectTask(task)} className="block text-left break-words text-sm text-yellow-400 py-1">
              {task.id} · {task.title} · unlisted
            </button>
            <TaskTelemetry task={task} />
          </div>
        ))}
      </Card>}
    </div>
  );
};
