import type { Task } from '../types';

export function duration(seconds: number | null | undefined) {
  if (seconds == null) return '未采集';
  const minutes = Math.round(seconds / 60);
  return `${minutes} 分钟`;
}

export function TaskTelemetry({ task }: { task: Task }) {
  const t = task.telemetry;
  const fields = [
    ['派发→首个提交', duration(t?.dispatch_to_first_commit_seconds)],
    ['首个提交→验收', duration(t?.commit_to_acceptance_seconds)],
    ['总耗时', duration(t?.total_seconds)],
    ['交付提交数', t?.delivery_commit_count == null ? '未采集' : `${t.delivery_commit_count} 次`],
    ['验收轮次（打回）', t?.rejection_count == null ? '未采集' : `${t.rejection_count} 次${t.rejection_count === 0 && task.board_status === '完成' ? '（一次通过）' : ''}`],
    ['累计额度', t?.quota_used ?? '未采集'],
  ];
  return <dl aria-label={`${task.id} 实测遥测`}
    title={[...(t?.missing_reasons ?? []), t?.quota_reason ?? '未采集：当前接口没有遥测数据。'].join('\n')}
    className="grid grid-cols-2 gap-x-3 gap-y-1.5 pt-2 border-t border-slate-800/60 text-[11px]">
    {fields.map(([label, value]) => <div key={label}>
      <dt className="text-slate-500">{label}</dt>
      <dd className="text-slate-300 font-mono">{value}</dd>
    </div>)}
  </dl>;
}
