import { useEffect, useState } from 'react';
import { FRESHNESS_CONFIG } from '../design-system/tokens';

export function dataAge(lastRefreshedAt: string | null, now = Date.now()) {
  if (!lastRefreshedAt) return null;
  const at = Date.parse(lastRefreshedAt);
  return Number.isFinite(at) ? Math.max(0, Math.floor((now - at) / 1000)) : null;
}

export function DataTime({ at, error, staticMode = false, failure = null, successAt = null }: {
  at: string | null; error: boolean; staticMode?: boolean;
  failure?: { at: string; reason: string } | null; successAt?: string | null;
}) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);
  const age = dataAge(at, now);
  const stale = error || (age !== null && age > 20 * 60);
  const freshness = age === null ? 'unknown' : age < 10 * 60 ? 'fresh' : age <= 20 * 60 ? 'stale' : 'unavailable';
  const color = FRESHNESS_CONFIG[freshness];
  const date = age === null || !at ? null : new Date(at);
  const pad = (value: number) => String(value).padStart(2, '0');
  const exportedAt = date
    ? `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
    : '暂无';
  const failureTime = failure ? Date.parse(failure.at) : NaN;
  const successTime = successAt ? Date.parse(successAt) : NaN;
  const showFailure = Number.isFinite(failureTime) && (!Number.isFinite(successTime) || failureTime > successTime);
  const successDate = Number.isFinite(successTime) ? new Date(successTime).toLocaleString() : null;
  const reason = Array.from((failure?.reason || '未知原因').split(/\r?\n/, 1)[0]).slice(0, 100).join('');
  return (
    <div role="status" className="border-b border-slate-800 bg-slate-950 px-4 py-2 text-xs sm:px-6 lg:px-8">
      {showFailure && <div className="mx-auto mb-2 max-w-7xl rounded border border-red-500 bg-red-950 px-3 py-2 text-red-200">
        上一次导出失败：{reason}，数据停留在 {successDate ?? '暂无成功导出'}
      </div>}
      <div className="mx-auto flex max-w-7xl flex-wrap items-center gap-x-4 gap-y-1">
        <span className={`inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 font-medium ${color.bg} ${color.text} ${color.border}`}>
          <span className={`h-1.5 w-1.5 rounded-full ${color.dot}`} />
          快照年龄：{age === null ? '未知' : `${Math.floor(age / 60)} 分钟`}
        </span>
        <span className="text-slate-300">上一次成功导出：{exportedAt}</span>
        {stale && <span className="text-amber-400">{staticMode ? '正在等下一份快照（快照每 10 分钟刷新一次）' : '正在重试'}</span>}
      </div>
    </div>
  );
}
