import React from 'react';
import type { DerivedStatus, EventState, SourceMeta, Node, Event } from '../types';
import {
  DERIVED_STATUS_CONFIG,
  EVENT_STATE_CONFIG,
  FRESHNESS_CONFIG,
  NODE_STATUS_CONFIG,
  SEVERITY_CONFIG,
} from './tokens';

interface BaseBadgeProps {
  size?: 'sm' | 'md' | 'lg';
  showDot?: boolean;
  className?: string;
}

export const DerivedStatusBadge: React.FC<BaseBadgeProps & { status: DerivedStatus }> = ({
  status,
  size = 'md',
  showDot = true,
  className = '',
}) => {
  const config = DERIVED_STATUS_CONFIG[status] || DERIVED_STATUS_CONFIG.unknown;
  const sizeClasses =
    size === 'sm'
      ? 'px-2 py-0.5 text-xs'
      : size === 'lg'
      ? 'px-3 py-1.5 text-sm font-semibold'
      : 'px-2.5 py-1 text-xs font-medium';

  return (
    <span
      title={`${config.label} - ${config.description}`}
      className={`inline-flex items-center gap-1.5 rounded-full border ${config.bg} ${config.text} ${config.border} ${sizeClasses} ${className} font-mono tracking-tight shadow-xs`}
    >
      {showDot && <span className={`h-1.5 w-1.5 rounded-full ${config.dot}`} />}
      <span>{config.shortLabel}</span>
    </span>
  );
};

export const EventStateBadge: React.FC<BaseBadgeProps & { state: EventState }> = ({
  state,
  size = 'md',
  showDot = true,
  className = '',
}) => {
  const key = state === null ? 'null' : state;
  const config = EVENT_STATE_CONFIG[key] || EVENT_STATE_CONFIG['null'];
  const sizeClasses =
    size === 'sm'
      ? 'px-2 py-0.5 text-xs'
      : size === 'lg'
      ? 'px-3 py-1.5 text-sm font-semibold'
      : 'px-2.5 py-1 text-xs font-medium';

  return (
    <span
      title={`${config.label}: ${config.description}`}
      className={`inline-flex items-center gap-1.5 rounded-md border ${config.bg} ${config.text} ${config.border} ${sizeClasses} ${className} font-mono`}
    >
      {showDot && <span className={`h-1.5 w-1.5 rounded-full ${config.dot}`} />}
      <span>{config.shortLabel}</span>
    </span>
  );
};

export const FreshnessBadge: React.FC<BaseBadgeProps & { freshness: SourceMeta['freshness']; stale?: boolean }> = ({
  freshness,
  stale,
  size = 'md',
  showDot = true,
  className = '',
}) => {
  const config = FRESHNESS_CONFIG[freshness] || FRESHNESS_CONFIG.unknown;
  const sizeClasses = size === 'sm' ? 'px-2 py-0.5 text-xs' : 'px-2.5 py-1 text-xs';

  return (
    <span
      title={`Freshness: ${config.label} (${stale ? 'stale=true' : 'stale=false'})`}
      className={`inline-flex items-center gap-1.5 rounded-md border ${config.bg} ${config.text} ${config.border} ${sizeClasses} ${className} font-mono font-medium`}
    >
      {showDot && <span className={`h-1.5 w-1.5 rounded-full ${config.dot}`} />}
      <span>{config.shortLabel}</span>
      {stale && <span className="opacity-75 text-[10px]">(STALE)</span>}
    </span>
  );
};

export const NodeStatusBadge: React.FC<BaseBadgeProps & { status: Node['status'] }> = ({
  status,
  size = 'md',
  showDot = true,
  className = '',
}) => {
  const config = NODE_STATUS_CONFIG[status] || NODE_STATUS_CONFIG.never;
  const sizeClasses = size === 'sm' ? 'px-2 py-0.5 text-xs' : 'px-2.5 py-1 text-xs';

  return (
    <span
      title={`Node Status: ${config.label}`}
      className={`inline-flex items-center gap-1.5 rounded-full border ${config.bg} ${config.text} ${config.border} ${sizeClasses} ${className} font-mono font-medium`}
    >
      {showDot && <span className={`h-1.5 w-1.5 rounded-full ${config.dot}`} />}
      <span>{config.shortLabel}</span>
    </span>
  );
};

export const SeverityBadge: React.FC<BaseBadgeProps & { severity: Event['severity'] }> = ({
  severity,
  size = 'sm',
  className = '',
}) => {
  const config = SEVERITY_CONFIG[severity] || SEVERITY_CONFIG.unknown;
  const sizeClasses = size === 'sm' ? 'px-1.5 py-0.5 text-[10px]' : 'px-2.5 py-1 text-xs';

  return (
    <span
      className={`inline-flex items-center gap-1 rounded-sm border uppercase font-mono font-bold ${config.bg} ${config.text} ${config.border} ${sizeClasses} ${className}`}
    >
      <span>{config.shortLabel}</span>
    </span>
  );
};

export const BoardStatusBadge: React.FC<{ status: string | null }> = ({ status }) => {
  if (!status) {
    return <span className="text-xs text-slate-500 font-mono">-</span>;
  }
  const colorMap: Record<string, string> = {
    待领: 'bg-slate-800 text-slate-300 border-slate-700',
    进行中: 'bg-blue-950/80 text-blue-300 border-blue-800',
    待验收: 'bg-amber-950/80 text-amber-300 border-amber-800',
    完成: 'bg-emerald-950/80 text-emerald-300 border-emerald-800',
    失败: 'bg-red-950/80 text-red-300 border-red-800',
    拒收: 'bg-rose-950/80 text-rose-300 border-rose-800',
  };
  const cls = colorMap[status] || 'bg-slate-900 text-slate-400 border-slate-800';

  return (
    <span
      title={`BOARD 六态原始值: ${status}`}
      className={`inline-block px-2 py-0.5 text-xs rounded border ${cls} font-sans`}
    >
      {status}
    </span>
  );
};

export const MockBadge: React.FC<{ className?: string }> = ({ className = '' }) => {
  return (
    <span
      className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded border border-amber-500/40 bg-amber-500/10 text-amber-300 text-[11px] font-mono font-semibold uppercase tracking-wider ${className}`}
    >
      <span className="h-1.5 w-1.5 rounded-full bg-amber-400 animate-pulse" />
      SYNTHETIC / MOCK
    </span>
  );
};
