export const COMMAND_UNAVAILABLE = '未连接本地控制层，指令不可用';
export const COMMAND_AUTH_ERROR = '指令 token 不正确';

export type CommandTarget = 'node-1' | 'node-2' | 'node-3' | 'total';
export type CommandRequest =
  | { action: 'dispatch'; target: CommandTarget; payload: { title: string; assignee: string; body_markdown: string } }
  | { action: 'board_status'; target: 'total'; payload: { task_id: string; status: '完成' | '进行中' | '待领' | '拒收' } }
  | { action: 'notify_node'; target: Exclude<CommandTarget, 'total'>; payload: { node: string; message: string } }
  | { action: 'query'; target: 'total'; payload: { question: string } }
  | { action: 'cancel'; target: 'total'; payload: { cancel_id: string } };

export interface CommandEntry {
  id: string;
  action: string;
  target: string;
  created_at: string;
  status?: string;
  result?: { status: string; detail?: string; by?: string; at?: string; artifacts?: string[] } | null;
}

export interface CommandLists {
  pending: CommandEntry[];
  done: CommandEntry[];
}

async function request(path: '/api/command' | '/api/commands', token: string, options: RequestInit = {}): Promise<unknown> {
  try {
    const response = await fetch(path, {
      ...options,
      headers: { Accept: 'application/json', 'X-CT-Command-Token': token, ...(options.body ? { 'Content-Type': 'application/json' } : {}) },
      cache: 'no-store',
      signal: AbortSignal.timeout(15_000),
    });
    if (response.status === 401) throw new Error(COMMAND_AUTH_ERROR);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return await response.json();
  } catch (error) {
    if (error instanceof Error && error.message === COMMAND_AUTH_ERROR) throw error;
    throw new Error(COMMAND_UNAVAILABLE);
  }
}

function isEntry(value: unknown): value is CommandEntry {
  if (!value || typeof value !== 'object') return false;
  const entry = value as CommandEntry;
  return ['id', 'action', 'target', 'created_at'].every(key =>
    typeof entry[key as keyof CommandEntry] === 'string'
  ) && (entry.status === undefined || typeof entry.status === 'string') &&
    (entry.result == null || (typeof entry.result === 'object' && typeof entry.result.status === 'string'));
}

export async function listCommands(token: string): Promise<CommandLists> {
  const data = await request('/api/commands', token) as CommandLists | null;
  if (!data || !Array.isArray(data.pending) || !Array.isArray(data.done) ||
      !data.pending.every(isEntry) || !data.done.every(isEntry)) {
    throw new Error(COMMAND_UNAVAILABLE);
  }
  return data;
}

export async function submitCommand(command: CommandRequest, token: string, staticMode = false): Promise<{ id: string }> {
  if (staticMode) throw new Error(COMMAND_UNAVAILABLE);
  const data = await request('/api/command', token, { method: 'POST', body: JSON.stringify(command) }) as { id?: unknown } | null;
  if (!data || typeof data.id !== 'string' || !data.id.startsWith('CMD-')) {
    throw new Error(COMMAND_UNAVAILABLE);
  }
  return { id: data.id };
}
