export interface ExportStatus {
  last_attempt_at: string | null;
  last_success_at: string | null;
  last_failure_at: string | null;
  last_failure_reason: string | null;
}

export async function loadExportStatus(): Promise<ExportStatus | null> {
  try {
    const response = await fetch('./export-status.json', { credentials: 'omit', cache: 'no-store' });
    if (!response.ok) return null;
    const data: unknown = await response.json();
    if (!data || typeof data !== 'object') return null;
    const status = data as ExportStatus;
    if (status.last_failure_at !== null && typeof status.last_failure_at !== 'string') return null;
    if (status.last_success_at !== null && typeof status.last_success_at !== 'string') return null;
    if (status.last_failure_reason !== null && typeof status.last_failure_reason !== 'string') return null;
    return status;
  } catch {
    return null;
  }
}
